    }

    function _policy(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        IStreamFinalityCoordinatorInventory.Coordinator memory original
    ) private view returns (StreamFinalityCoordinatorPolicyV2 memory e) {
        address target = original.coordinator;
        if (target.code.length == 0 || target.codehash != original.indexedCodeHash) {
            revert PolicyDependency(target);
        }
        _word(
            target,
            abi.encodeWithSignature("core()"),
            bytes32(uint256(uint160(d.targets[0]))),
            d.readGas
        );
        _supports(target, type(IStreamEntropyCoordinator).interfaceId, d.readGas);
        _supports(target, type(IStreamEntropyFinalityPolicy).interfaceId, d.readGas);
        _supports(target, type(IStreamModule).interfaceId, d.readGas);
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleType, ()),
            keccak256("ENTROPY_COORDINATOR"),
            d.readGas
        );
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleInterfaceId, ()),
            bytes32(type(IStreamEntropyCoordinator).interfaceId),
            d.readGas
        );
        _word(
            target,
            abi.encodeCall(IStreamModule.streamModuleCodeHash, ()),
            original.indexedCodeHash,
            d.readGas
        );
        e.coordinator = target;
        e.indexedCodeHash = original.indexedCodeHash;
        e.firstTokenIndex = original.firstTokenIndex;
        (e.moduleVersion, e.moduleManifestHash) =
            StreamFinalityRouterEvidence.moduleIdentity(target, d.readGas);
        e.moduleSchemaHash = abi.decode(
            _read(target, abi.encodeCall(IStreamModule.streamModuleSchemaHash, ()), 32, d.readGas),
            (bytes32)
        );
        e.deploymentManifestHash = abi.decode(
            _read(
                target,
                abi.encodeCall(IStreamModule.streamModuleDeploymentManifestHash, ()),
                32,
                d.readGas
            ),
            (bytes32)
        );
        bool explicitCap = abi.decode(
            _read(target, abi.encodeCall(IERC165.supportsInterface, (P.CAPABILITY)), 32, d.readGas),
            (bool)
        );
        if (explicitCap) {
            bytes memory encoded = _read(
                target,
                abi.encodeCall(ExplicitRead.collectionEntropyPolicy, (scope.collectionId)),
                384,
                d.readGas
            );
            P.Policy memory policy = abi.decode(encoded, (P.Policy));
            if (keccak256(encoded) != keccak256(abi.encode(policy))) {
                revert PolicyUnavailable(target);
            }
            if (policy.explicitPolicy) {
                e.collectionPolicy =
                    Explicit.policy(target, d.targets[0], scope.collectionId, d.readGas);
                e.explicitPolicy = true;
                e.frozen = e.collectionPolicy.frozen;
                e.policyHash = e.collectionPolicy.policyHash;
                if (e.moduleSchemaHash == 0 || e.deploymentManifestHash == 0) {
                    revert PolicyUnavailable(target);
                }
                // Explicit V2 never borrows V1 provider/epoch/salt or its evidence identity.
                // The original five-word API must remain unavailable for this policy.
                bytes memory unavailable = _read(
                    target,
                    abi.encodeCall(
                        IStreamEntropyFinalityPolicy.entropyPolicyFrozen, (scope.collectionId)
                    ),
                    160,
                    d.readGas
                );
                if (keccak256(unavailable) != keccak256(new bytes(160))) {
                    revert PolicyUnavailable(target);
                }
                e.componentDataHash = keccak256(
                    abi.encode(
                        keccak256("6529STREAM_ENTROPY_COMPONENT_EVIDENCE_V2"),
                        d.chainId,
                        d.targets[0],
                        target,
                        scope,
                        e.collectionPolicy
                    )
                );
                return e;
            }
        }
        bytes memory raw = _read(
            target,
            abi.encodeCall(IStreamEntropyFinalityPolicy.entropyPolicyFrozen, (scope.collectionId)),
            160,
            d.readGas
        );
        (e.frozen, e.policyHash, e.provider, e.epoch, e.salt) =
            abi.decode(raw, (bool, bytes32, address, uint32, bytes32));
        if (
            e.moduleSchemaHash == 0 || e.deploymentManifestHash == 0 || e.policyHash == 0
                || e.provider == address(0) || e.epoch == 0 || e.salt == 0
                || keccak256(raw)
                    != keccak256(abi.encode(e.frozen, e.policyHash, e.provider, e.epoch, e.salt))
        ) {
            revert PolicyUnavailable(target);
        }
        // Identical per-source preimage to the original single-coordinator evidence provider.
        e.componentDataHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_ENTROPY_COMPONENT_EVIDENCE_V1"),
                d.chainId,
                d.targets[0],
                target,
                scope,
                e.policyHash,
                e.provider,
                e.epoch,
                e.salt
            )
        );
    }

    function _bindings(Dependencies memory d) private view {
        if (d.chainId != block.chainid || d.readGas < 50000 || d.inventoryGas < d.readGas) {
            revert PolicyConfiguration();
        }
        for (uint256 i; i < 4; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert PolicyDependency(d.targets[i]);
            }
        }
        _supports(d.targets[0], 0x80ac58cd, d.readGas);
        _supports(d.targets[2], type(IStreamFinalityScopeMembership).interfaceId, d.readGas);
        _supports(d.targets[3], type(IStreamFinalityCoordinatorInventory).interfaceId, d.readGas);
        for (uint256 i = 1; i < 4; ++i) {
            _word(
                d.targets[i],
                abi.encodeWithSignature("core()"),
                bytes32(uint256(uint160(d.targets[0]))),
                d.readGas
            );
        }
        _word(
            d.targets[2],
            abi.encodeWithSignature("metadataHost()"),
            bytes32(uint256(uint160(d.targets[1]))),
            d.readGas
        );
        _word(
            d.targets[3],
            abi.encodeWithSignature("scopeMembershipHost()"),
            bytes32(uint256(uint160(d.targets[2]))),
            d.readGas
        );
        _word(
            d.targets[3],
            abi.encodeWithSignature("deploymentChainId()"),
            bytes32(d.chainId),
            d.readGas
        );
        _word(d.targets[3], abi.encodeWithSignature("coreCodeHash()"), d.codeHashes[0], d.readGas);
        _word(
            d.targets[3],
            abi.encodeWithSignature("scopeMembershipCodeHash()"),
            d.codeHashes[2],
            d.readGas
        );
    }

    function _supports(address target, bytes4 id, uint32 cap) private view {
        _word(target, abi.encodeCall(IERC165.supportsInterface, (id)), bytes32(uint256(1)), cap);
        _word(
            target,
            abi.encodeCall(IERC165.supportsInterface, (type(IERC165).interfaceId)),
            bytes32(uint256(1)),
            cap
        );
        _word(
            target, abi.encodeCall(IERC165.supportsInterface, (bytes4(0xffffffff))), bytes32(0), cap
        );
    }

    function _word(address target, bytes memory input, bytes32 expected, uint32 cap) private view {
        if (abi.decode(_read(target, input, 32, cap), (bytes32)) != expected) {
            revert PolicyDependency(target);
        }
    }

    function _read(address target, bytes memory input, uint256 size, uint32 cap)
        private
        view
        returns (bytes memory out)
    {
        out = new bytes(size);
        if (gasleft() <= uint256(cap) + uint256(cap) / 63 + 10000) {
            revert PolicyRead(target, bytes4(input));
        }
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(out, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert PolicyRead(target, bytes4(input));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/StreamFinalityDescriptionTypes.sol";
import "../../interfaces/stream/metadata/IStreamWorkRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamRightsRecordSelection.sol";
import "../../interfaces/stream/metadata/IStreamCollectionRecordReceipts.sol";
import "../metadata/StreamMetadataSubjects.sol";
import "../records/StreamWorkRecordDefinitions.sol";
import "../records/StreamRightsRecordDefinitions.sol";

/// @notice Joins current WORK and RIGHTS heads to their actual original metadata receipts.
/// @dev The consuming provider supplies constructor-fixed dependencies, including predicted late
///      selector addresses and exact expected runtime hashes. No caller-selected dependency graph,
///      mutable binding phase, collection-to-token inheritance or complete finality claim is added.
library StreamFinalityDescriptionReads {
    struct Dependencies {
        // Core, generic metadata, schemas, byte store, WORK selector, RIGHTS selector.
        address[6] targets;
        bytes32[6] codeHashes;
        uint256 chainId;
        uint256 readGas;
        uint256 selectionGas;
    }

    error DescriptionConfiguration();
    error DescriptionDependency(address target);
    error DescriptionRead(address target, bytes4 selector);
    error DescriptionSelection(address target, bytes32 recordHash);
    error DescriptionReceipt(bytes32 recordHash);

    function requireCurrent(Dependencies memory d, StreamFinalityScope memory scope)
        public
        view
        returns (StreamFinalityDescriptionEvidence memory e)
    {
        _bindings(d);
        e.scopeSubject = StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope);
        IStreamWorkRecordSelection.Selection memory work =
            _work(d, scope.collectionId, e.scopeSubject);
        IStreamRightsRecordSelection.Selection memory rights =
            _rights(d, scope.collectionId, e.scopeSubject);
        e.workDescriptionRecordHash = work.recordHash;
        e.rightsStatementRecordHash = rights.recordHash;
        e.workPayloadHash = work.payloadHash;
        e.rightsPayloadHash = rights.payloadHash;
        e.workSelectionHash = work.selectionHash;
        e.rightsSelectionHash = rights.selectionHash;
        e.workRevision = work.revision;
        e.rightsRevision = rights.revision;
    }

    function _work(Dependencies memory d, uint256 cid, bytes32 subject)
        private
        view
        returns (IStreamWorkRecordSelection.Selection memory selected)
    {
        bytes memory raw = _read(
            d.targets[4],
            abi.encodeCall(IStreamWorkRecordSelection.currentWork, (cid, subject)),
            1056,
            d.readGas
        );
        selected = abi.decode(raw, (IStreamWorkRecordSelection.Selection));
        if (
            selected.recordHash == 0 || selected.payloadHash == 0 || selected.revision == 0
                || keccak256(raw) != keccak256(abi.encode(selected))
        ) revert DescriptionSelection(d.targets[4], selected.recordHash);
        bytes32 retained = selected.selectionHash;
        selected.selectionHash = 0;
        bytes32 computed = keccak256(
            abi.encode(
                keccak256("6529STREAM_WORK_SELECTION_V1"),
                d.chainId,
                d.targets[4],
                d.targets[0],
                d.targets[1],
                d.targets[2],
                d.targets[3],
                cid,
                subject,
                selected
            )
        );
        selected.selectionHash = retained;
        if (retained != computed) revert DescriptionSelection(d.targets[4], selected.recordHash);
        bytes memory current = _read(
            d.targets[4],
            abi.encodeCall(
                IStreamWorkRecordSelection.requireCurrent,
                (cid, subject, selected.recordHash, selected.revision)
            ),
            1056,
            d.selectionGas
        );
        if (keccak256(current) != keccak256(raw)) {
            revert DescriptionSelection(d.targets[4], selected.recordHash);
        }
        IStreamCollectionMetadataV1.RecordReceipt memory receipt = _receipt(d, selected.recordHash);
        if (
            receipt.collectionId != cid || receipt.recordIndex != selected.recordIndex
                || receipt.recorder != selected.recorder
                || receipt.authorizationClass != selected.recorderAuthorizationClass
                || receipt.recordChainHash != selected.recordChainHash
                || receipt.schemaDefinitionHash != StreamWorkRecordDefinitions.SCHEMA_HASH
                || receipt.canonicalizationDefinitionHash != StreamWorkRecordDefinitions.CANON_HASH
                || receipt.artistAuthorization != selected.artistPublication.attestationRecordHash
        ) revert DescriptionReceipt(selected.recordHash);
    }

    function _rights(Dependencies memory d, uint256 cid, bytes32 subject)
        private
        view
        returns (IStreamRightsRecordSelection.Selection memory selected)
    {
        bytes memory raw = _read(
            d.targets[5],
            abi.encodeCall(IStreamRightsRecordSelection.currentRights, (cid, subject)),
            448,
            d.readGas
        );
        selected = abi.decode(raw, (IStreamRightsRecordSelection.Selection));
        if (
            selected.recordHash == 0 || selected.payloadHash == 0 || selected.revision == 0
                || keccak256(raw) != keccak256(abi.encode(selected))
        ) revert DescriptionSelection(d.targets[5], selected.recordHash);
        bytes32 retained = selected.selectionHash;
        selected.selectionHash = 0;
        bytes32 computed = keccak256(
            abi.encode(
                keccak256("6529STREAM_RIGHTS_SELECTION_V1"),
                d.chainId,
                d.targets[5],
                d.targets[0],
                d.targets[1],
                d.targets[2],
                d.targets[3],
                cid,
                subject,
                selected
            )
        );
        selected.selectionHash = retained;
        if (retained != computed) revert DescriptionSelection(d.targets[5], selected.recordHash);
        bytes memory current = _read(
            d.targets[5],
            abi.encodeCall(
                IStreamRightsRecordSelection.requireCurrent,
                (cid, subject, selected.recordHash, selected.revision)
            ),
            448,
            d.selectionGas
        );
        if (keccak256(current) != keccak256(raw)) {
            revert DescriptionSelection(d.targets[5], selected.recordHash);
        }
        IStreamCollectionMetadataV1.RecordReceipt memory receipt = _receipt(d, selected.recordHash);
        if (
            receipt.collectionId != cid || receipt.recordIndex != selected.recordIndex
                || receipt.recorder != selected.recorder
                || receipt.authorizationClass != selected.recorderAuthorizationClass
                || receipt.schemaDefinitionHash != StreamRightsRecordDefinitions.SCHEMA_HASH
                || receipt.canonicalizationDefinitionHash
                    != StreamRightsRecordDefinitions.CANON_HASH
        ) revert DescriptionReceipt(selected.recordHash);
    }

    function _receipt(Dependencies memory d, bytes32 hash)
        private
        view
        returns (IStreamCollectionMetadataV1.RecordReceipt memory r)
    {
        bytes memory raw = _read(
            d.targets[1],
            abi.encodeCall(IStreamCollectionRecordReceipts.collectionRecordReceipt, (hash)),
            288,
            d.readGas
        );
        r = abi.decode(raw, (IStreamCollectionMetadataV1.RecordReceipt));
        if (keccak256(raw) != keccak256(abi.encode(r))) revert DescriptionReceipt(hash);
    }

    function _bindings(Dependencies memory d) private view {
        if (
            block.chainid != d.chainId || d.readGas == 0 || d.selectionGas < d.readGas
                || d.selectionGas > type(uint256).max / 64
        ) {
            revert DescriptionConfiguration();
        }
        for (uint256 i; i < 6; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert DescriptionDependency(d.targets[i]);
            }
        }
        bytes4[4] memory addressSelectors = [
            IStreamWorkRecordSelection.core.selector,
            IStreamWorkRecordSelection.metadata.selector,
            IStreamWorkRecordSelection.schemaRegistry.selector,
            IStreamWorkRecordSelection.chunkStore.selector
        ];
        bytes4[4] memory hashSelectors = [
            IStreamWorkRecordSelection.coreCodeHash.selector,
            IStreamWorkRecordSelection.metadataCodeHash.selector,
            IStreamWorkRecordSelection.schemaRegistryCodeHash.selector,
            IStreamWorkRecordSelection.chunkStoreCodeHash.selector
        ];
        for (uint256 i = 4; i < 6; ++i) {
            for (uint256 j; j < 4; ++j) {
                _word(
                    d,
                    i,
                    abi.encodeWithSelector(addressSelectors[j]),
                    bytes32(uint256(uint160(d.targets[j])))
                );
                _word(d, i, abi.encodeWithSelector(hashSelectors[j]), d.codeHashes[j]);
            }
            _word(
                d,
                i,
                abi.encodeCall(IStreamWorkRecordSelection.deploymentChainId, ()),
                bytes32(d.chainId)
            );
            _word(
                d,
                i,
                abi.encodeCall(
                    IERC165.supportsInterface,
                    (i == 4
                            ? type(IStreamWorkRecordSelection).interfaceId
                            : type(IStreamRightsRecordSelection).interfaceId)
                ),
                bytes32(uint256(1))
            );
        }
        // requireCurrent on each original selector verifies its reciprocal metadata/artist graph,
        // selected Core host and complete active definition bytes. Do not replay the old grants.
    }

    function _word(Dependencies memory d, uint256 target, bytes memory input, bytes32 expected)
        private
        view
    {
        if (abi.decode(_read(d.targets[target], input, 32, d.readGas), (bytes32)) != expected) {
            revert DescriptionDependency(d.targets[target]);
        }
    }

    function _read(address target, bytes memory input, uint256 size, uint256 cap)
        private
        view
        returns (bytes memory out)
    {
        out = new bytes(size);
        if (gasleft() <= cap + cap / 63 + 10000) revert DescriptionRead(target, bytes4(input));
        bool ok;
        uint256 returned;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(out, 32), size)
            returned := returndatasize()
        }
        if (!ok || returned != size) revert DescriptionRead(target, bytes4(input));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamPreservationPolicyReferenceFamiliesV2 as F
} from "../preservation/StreamPreservationPolicyReferenceFamiliesV2.sol";
import {
    StreamPreservationTokenProducerProfilesV1 as Profiles
} from "../../interfaces/stream/finality/StreamPreservationTokenProducerProfilesV1.sol";

import {
    StreamPreservationPolicyReferenceTypesV1 as T
} from "../../interfaces/stream/preservation/StreamPreservationPolicyReferenceTypesV1.sol";
import {
    StreamReferenceRenderTypes as R
} from "../../interfaces/stream/preservation/StreamReferenceRenderTypes.sol";
import {
    IStreamPreservationPolicyReferencePublicationV1 as P
} from "../../interfaces/stream/preservation/IStreamPreservationPolicyReferencePublicationV1.sol";
import {
    StreamPreservationPolicyReferenceDefinitionsV1 as D
} from "../records/StreamPreservationPolicyReferenceDefinitionsV1.sol";
import { StreamMetadataSubjects } from "../metadata/StreamMetadataSubjects.sol";
import { StreamFinalityRouterEvidence as Reads } from "./StreamFinalityRouterEvidence.sol";
import {
    StreamFinalityScope,
    StreamFinalityScopeType,
    StreamFinalityDomains,
    StreamFinalityComponentState,
    IStreamArtworkScopedFinalityComponent
} from "../../interfaces/stream/finality/IStreamArtworkFinalityComponents.sol";

/// @notice Exact COLLECTION preservation V1 reference records and current terminal lock for fixed providers.
/// @dev Caller supplies its constructor-pinned dependency configuration, never a per-request host.
/// These observations do not replace the complete render-critical inventory or archive.
library StreamFinalityPreservationPolicyReferenceReadsV1 {
    struct Dependencies {
        // Core, selected Metadata, Router, preservation collection snapshots, preservation reference publisher.
        address[5] targets;
        bytes32[5] codeHashes;
        uint256 chainId;
        uint256 readGas;
        uint256 sourceGas;
    }
    error InvalidPolicyReferenceEvidence();
    error PolicyReferenceDependency(address source);

    function requireBindings(Dependencies memory d) public view {
        requireBindings(d, Profiles.ORIGINAL_PROFILE);
    }

    function requireBindings(Dependencies memory d, bytes32 family) public view {
        F.isV2(family);
        if (d.chainId != block.chainid || d.readGas < 50000 || d.sourceGas < d.readGas) {
            revert InvalidPolicyReferenceEvidence();
        }
        for (uint256 i; i < 5; ++i) {
            if (d.targets[i].code.length == 0 || d.targets[i].codehash != d.codeHashes[i]) {
                revert PolicyReferenceDependency(d.targets[i]);
            }
        }
        if (
            abi.decode(
                        Reads.read(
                            d.targets[4],
                            abi.encodeWithSignature(
                                "supportsInterface(bytes4)", type(P).interfaceId
                            ),
                            32,
                            d.readGas
                        ),
                        (uint256)
                    ) != 1
                || abi.decode(
                        Reads.read(
                            d.targets[4],
                            abi.encodeCall(P.preservationPolicyReferenceProfile, ()),
                            32,
                            d.readGas
                        ),
                        (bytes32)
                    ) != F.profile(family, false)
        ) revert InvalidPolicyReferenceEvidence();
        bytes memory raw =
            Reads.read(d.targets[4], abi.encodeCall(P.dependencies, ()), 608, d.readGas);
        T.Dependencies memory source = abi.decode(raw, (T.Dependencies));
        _canonical(d.targets[4], raw, abi.encode(source));
        if (source.chainId != d.chainId) revert InvalidPolicyReferenceEvidence();
        uint256[4] memory indexes = [uint256(0), 1, 4, 5];
        // Publisher runtime is already pinned above; its first four shared roles match exactly.
        for (uint256 i; i < 4; ++i) {
            if (
                source.targets[indexes[i]] != d.targets[i]
                    || source.codeHashes[indexes[i]] != d.codeHashes[i]
            ) {
                revert PolicyReferenceDependency(d.targets[4]);
            }
        }
    }

    function original(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (T.Publication memory p, T.Receipt memory receipt) {
        return original(d, scope, hash, revision, Profiles.ORIGINAL_PROFILE);
    }

    function original(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision,
        bytes32 family
    ) public view returns (T.Publication memory p, T.Receipt memory receipt) {
        F.Definition memory definition = F.definition(family, false);
        requireBindings(d, family);
        bytes32 subject = _subject(d, scope);
        bytes memory raw = Reads.dynamicRead(
            d.targets[4], abi.encodeCall(P.referenceRecord, (hash)), 524960, d.sourceGas
        );
        (p, receipt) = abi.decode(raw, (T.Publication, T.Receipt));
        _canonical(d.targets[4], raw, abi.encode(p, receipt));
        R.Receipt memory r = receipt.observation;
        R.Publication memory o = p.observation;
        if (
            hash == 0 || revision == 0 || receipt.scopeSubject != subject
                || keccak256(abi.encode(p.scope)) != keccak256(abi.encode(scope))
                || o.collectionId != scope.collectionId || r.collectionId != scope.collectionId
                || r.recordHash != hash || r.revision != revision || o.referenceId != r.referenceId
                || r.referenceId == 0 || o.expectedHead != r.predecessor
                || o.expectedRevision == type(uint64).max || o.expectedRevision + 1 != revision
                || o.expectedSourcesHash != r.sourcesHash || r.sourcesHash == 0
                || o.snapshotRecordHash != r.snapshotRecordHash || r.snapshotRecordHash == 0
                || o.snapshotRevision != r.snapshotRevision || r.snapshotRevision == 0
                || r.payloadHash == 0 || r.payloadBytes == 0 || r.payloadBytes > 524288
                || r.recordChainHash == 0 || r.recorder == address(0)
                || (r.authorizationClass != 3 && r.authorizationClass != 8) || r.grantRevision == 0
                || o.effectiveAt != r.effectiveAt || r.effectiveAt == 0
                || o.reasonHash != r.reasonHash || r.reasonHash == 0 || r.recordedAt == 0
                || r.effectiveAt > r.recordedAt || r.recordedAt > block.timestamp
                || r.schemaHash != definition.schemaHash || r.profileHash != definition.profileHash
                || r.canonicalizationHash != definition.canonHash
        ) revert InvalidPolicyReferenceEvidence();
        // Original producer hashes the complete receipt before assigning these two final fields.
        T.Receipt memory fields = abi.decode(abi.encode(receipt), (T.Receipt));
        fields.observation.recordHash = 0;
        fields.observation.recordChainHash = 0;
        if (
            keccak256(
                    abi.encode(
                        F.recordDomain(family, false),
                        d.chainId,
                        d.targets[4],
                        d.targets[0],
                        d.targets[1],
                        p,
                        fields
                    )
                ) != hash
        ) {
            revert InvalidPolicyReferenceEvidence();
        }
    }

    function requireCurrent(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (T.Receipt memory receipt) {
        return requireCurrent(d, scope, hash, revision, Profiles.ORIGINAL_PROFILE);
    }

    function requireCurrent(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision,
        bytes32 family
    ) public view returns (T.Receipt memory receipt) {
        (, receipt) = original(d, scope, hash, revision, family);
        bytes memory raw = Reads.read(
            d.targets[4],
            abi.encodeCall(P.requireCurrent, (scope, hash, revision)),
            672,
            d.sourceGas
        );
        T.Receipt memory current = abi.decode(raw, (T.Receipt));
        _canonical(d.targets[4], raw, abi.encode(current));
        if (keccak256(abi.encode(current)) != keccak256(abi.encode(receipt))) {
            revert InvalidPolicyReferenceEvidence();
        }
    }

    function requireLocked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (T.Receipt memory receipt, R.Lock memory locked) {
        return requireLocked(d, scope, hash, revision, Profiles.ORIGINAL_PROFILE);
    }

    function requireLocked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision,
        bytes32 family
    ) public view returns (T.Receipt memory receipt, R.Lock memory locked) {
        receipt = requireCurrent(d, scope, hash, revision, family);
        bytes memory raw =
            Reads.read(d.targets[4], abi.encodeCall(P.referenceLock, (scope)), 128, d.readGas);
        locked = abi.decode(raw, (R.Lock));
        _canonical(d.targets[4], raw, abi.encode(locked));
        if (
            locked.actionId == 0 || locked.recordHash != hash || locked.revision != revision
                || locked.lockedAt < receipt.observation.recordedAt
                || locked.lockedAt > block.timestamp
        ) {
            revert InvalidPolicyReferenceEvidence();
        }
    }

    function component(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision
    ) public view returns (StreamFinalityComponentState memory state) {
        return component(d, scope, hash, revision, Profiles.ORIGINAL_PROFILE);
    }

    function component(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 hash,
        uint64 revision,
        bytes32 family
    ) public view returns (StreamFinalityComponentState memory state) {
        F.Definition memory definition = F.definition(family, false);
        (T.Receipt memory receipt, R.Lock memory locked) =
            requireLocked(d, scope, hash, revision, family);
        bytes memory raw = Reads.read(
            d.targets[4],
            abi.encodeCall(IStreamArtworkScopedFinalityComponent.finalityStateForScope, (scope)),
            256,
            d.sourceGas
        );
        state = abi.decode(raw, (StreamFinalityComponentState));
        _canonical(d.targets[4], raw, abi.encode(state));
        if (
            !state.frozen || state.componentType != StreamFinalityDomains.COMPONENT_REFERENCE_RENDER
                || state.component != d.targets[4] || state.codeHash != d.codeHashes[4]
                || state.interfaceId != type(IStreamArtworkScopedFinalityComponent).interfaceId
                || state.moduleVersion != F.moduleVersion(family, false)
                || state.manifestHash != definition.profileHash
                || state.dataHash
                    != keccak256(
                        abi.encode(
                            F.componentDomain(family, false),
                            d.chainId,
                            d.targets[4],
                            d.targets[0],
                            scope,
                            receipt,
                            locked
                        )
                    )
        ) revert InvalidPolicyReferenceEvidence();
    }

    function _subject(Dependencies memory d, StreamFinalityScope memory scope)
        private
        pure
        returns (bytes32)
    {
        if (
            scope.scopeType != StreamFinalityScopeType.COLLECTION || scope.collectionId == 0
                || scope.tokenId != 0 || scope.scopeId != 0
        ) revert InvalidPolicyReferenceEvidence();
        return StreamMetadataSubjects.scopeSubject(d.chainId, d.targets[0], scope);
    }

    function _canonical(address source, bytes memory raw, bytes memory encoded) private pure {
        if (keccak256(raw) != keccak256(encoded)) revert PolicyReferenceDependency(source);
    }
}

