pragma solidity ^0.8.19;
import {
    StreamFinalityScopedPreservationPolicySnapshotOriginalReadsV1 as OriginalReads
} from "./StreamFinalityScopedPreservationPolicySnapshotOriginalReadsV1.sol";
import {
    StreamPreservationTokenProducerProfilesV1 as Producers
} from "../../interfaces/stream/finality/StreamPreservationTokenProducerProfilesV1.sol";
import {
    StreamPreservationPolicySnapshotFamiliesV2 as SnapshotFamilies
} from "../records/StreamPreservationPolicySnapshotFamiliesV2.sol";

import {
    StreamScopedPreservationPolicySnapshotTypesV1 as S
} from "../../interfaces/stream/metadata/StreamScopedPreservationPolicySnapshotTypesV1.sol";
import {
    IStreamScopedPreservationPolicySnapshotPublicationV1 as Snapshot
} from "../../interfaces/stream/metadata/IStreamScopedPreservationPolicySnapshotPublicationV1.sol";
import { StreamFinalityRouterEvidence as Reads } from "./StreamFinalityRouterEvidence.sol";
import "../../interfaces/stream/finality/StreamFinalitySnapshotTypes.sol";
import {
    StreamFinalityScope
} from "../../interfaces/stream/finality/StreamArtworkFinalityTypes.sol";

/// @notice Current scoped preservation snapshot evidence from the distinct pinned producer.
/// @dev COLLECTION remains on its original reader. Snapshot evidence is not Artist root authority,
/// complete output-byte preservation, a reference acceptance mode, or aggregate finality readiness.
library StreamFinalityScopedPreservationPolicySnapshotReadsV1 {
    struct Dependencies {
        address core;
        address metadata;
        address router;
        address snapshots;
        bytes32 coreCodeHash;
        bytes32 metadataCodeHash;
        bytes32 routerCodeHash;
        bytes32 snapshotsCodeHash;
        uint256 chainId;
        uint256 readGas;
        uint256 validationGas;
    }

    // Preserve the reader ABI for the scope error now bubbled from its fixed worker.
    error InvalidMetadataScope();
    error InvalidScopedPreservationPolicySnapshotEvidence();

    function requireCurrent(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision
    ) public view returns (StreamFinalitySnapshotEvidence memory e) {
        return requireCurrent(d, scope, recordHash, revision, Producers.ORIGINAL_PROFILE);
    }

    function requireCurrent(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision,
        bytes32 family
    ) public view returns (StreamFinalitySnapshotEvidence memory e) {
        SnapshotFamilies.version2(family);
        (S.Publication memory p, S.Receipt memory r) =
            original(d, scope, recordHash, revision, family);
        bytes memory raw = Reads.read(
            d.snapshots,
            abi.encodeCall(Snapshot.requireCurrent, (scope, recordHash, revision)),
            544,
            d.validationGas
        );
        if (keccak256(raw) != keccak256(abi.encode(r))) {
            revert InvalidScopedPreservationPolicySnapshotEvidence();
        }
        raw = Reads.read(
            d.snapshots, abi.encodeCall(Snapshot.snapshotLock, (scope)), 128, d.readGas
        );
        S.Lock memory lock_ = abi.decode(raw, (S.Lock));
        _canonical(raw, abi.encode(lock_));
        bool locked = lock_.actionId != 0;
        if (locked) {
            if (
                lock_.recordHash != recordHash || lock_.revision != revision
                    || lock_.lockedAt < r.recordedAt || lock_.lockedAt > block.timestamp
            ) revert InvalidScopedPreservationPolicySnapshotEvidence();
        } else if (lock_.recordHash != 0 || lock_.revision != 0 || lock_.lockedAt != 0) {
            revert InvalidScopedPreservationPolicySnapshotEvidence();
        }
        e = StreamFinalitySnapshotEvidence(
            0,
            recordHash,
            r.manifestHash,
            r.sourceHash,
            p.coordinatorInventoryPlan,
            r.schemaHash,
            r.profileHash,
            r.canonicalizationHash,
            revision,
            r.manifestBytes,
            r.publisher,
            r.authorizationClass,
            r.grantRevision,
            r.displayAuthorizationClass,
            r.displayGrantRevision,
            locked,
            keccak256(
                abi.encode(
                    SnapshotFamilies.finalityLockDomain(family, true),
                    d.chainId,
                    d.snapshots,
                    scope,
                    lock_
                )
            )
        );
        e.inputHash = keccak256(
            abi.encode(
                SnapshotFamilies.inputDomain(family, true),
                d.chainId,
                d.core,
                d.metadata,
                d.router,
                d.snapshots,
                d.snapshotsCodeHash,
                scope,
                e
            )
        );
    }

    function requireLocked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision
    ) public view returns (StreamFinalitySnapshotEvidence memory e) {
        return requireLocked(d, scope, recordHash, revision, Producers.ORIGINAL_PROFILE);
    }

    function requireLocked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision,
        bytes32 family
    ) public view returns (StreamFinalitySnapshotEvidence memory e) {
        SnapshotFamilies.version2(family);
        e = requireCurrent(d, scope, recordHash, revision, family);
        if (!e.locked) revert InvalidScopedPreservationPolicySnapshotEvidence();
    }

    /// @notice Exact immutable original record; does not assert that it remains the current head.
    function original(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision
    ) public view returns (S.Publication memory p, S.Receipt memory r) {
        return original(d, scope, recordHash, revision, Producers.ORIGINAL_PROFILE);
    }

    function original(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision,
        bytes32 family
    ) public view returns (S.Publication memory p, S.Receipt memory r) {
        return OriginalReads.original(d, scope, recordHash, revision, family);
    }

    function _canonical(bytes memory supplied, bytes memory expected) private pure {
        if (keccak256(supplied) != keccak256(expected)) {
            revert InvalidScopedPreservationPolicySnapshotEvidence();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/finality/StreamFinalitySnapshotTypes.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityRegistry.sol";
import "../../interfaces/stream/metadata/IStreamCollectionSnapshots.sol";
import "../records/StreamSnapshotDefinitions.sol";
import {
    StreamChunkedSnapshotDefinitions as ChunkedDefinitions
} from "../records/StreamChunkedSnapshotDefinitions.sol";
import "./StreamFinalityRouterEvidence.sol";

/// @notice Current native snapshot evidence from a fixed actual authenticated producer.
/// @dev The producer revalidates complete source/manifest bytes. This is not archive coverage,
///      entropy-output proof, arbitrary JavaScript closure or full aggregate finality readiness.
library StreamFinalitySnapshotReads {
    struct Dependencies {
        address core;
        address metadata;
        address snapshots;
        bytes32 coreCodeHash;
        bytes32 metadataCodeHash;
        bytes32 snapshotsCodeHash;
        uint256 chainId;
        uint256 readGas;
        uint256 validationGas;
    }
    error InvalidSnapshotEvidence();

    function requireCurrent(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision
    ) public view returns (StreamFinalitySnapshotEvidence memory e) {
        return _current(d, scope, recordHash, revision, false);
    }

    function requireCurrentChunked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision
    ) public view returns (StreamFinalitySnapshotEvidence memory) {
        return _current(d, scope, recordHash, revision, true);
    }

    function requireLockedChunked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision
    ) public view returns (StreamFinalitySnapshotEvidence memory e) {
        e = _current(d, scope, recordHash, revision, true);
        if (!e.locked) revert InvalidSnapshotEvidence();
    }

    function _current(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision,
        bool chunked
    ) private view returns (StreamFinalitySnapshotEvidence memory e) {
        if (
            d.chainId != block.chainid || d.readGas < 50000 || d.validationGas < d.readGas
                || scope.scopeType != StreamFinalityScopeType.COLLECTION || scope.collectionId == 0
                || scope.tokenId != 0 || scope.scopeId != 0 || recordHash == 0 || revision == 0
        ) {
            revert InvalidSnapshotEvidence();
        }
        _pin(d.core, d.coreCodeHash);
        _pin(d.metadata, d.metadataCodeHash);
        _pin(d.snapshots, d.snapshotsCodeHash);
        if (
            _word(d, abi.encodeCall(IStreamCollectionSnapshots.core, ()))
                    != bytes32(uint256(uint160(d.core)))
                || _word(d, abi.encodeCall(IStreamCollectionSnapshots.metadataHost, ()))
                    != bytes32(uint256(uint160(d.metadata)))
        ) {
            revert InvalidSnapshotEvidence();
        }
        bytes memory raw = StreamFinalityRouterEvidence.dynamicRead(
            d.snapshots,
            abi.encodeCall(IStreamCollectionSnapshots.snapshotRecord, (recordHash)),
            4096,
            d.readGas
        );
        (StreamSnapshotTypes.Publication memory p, StreamSnapshotTypes.Receipt memory r) =
            abi.decode(raw, (StreamSnapshotTypes.Publication, StreamSnapshotTypes.Receipt));
        _canonical(raw, abi.encode(p, r));
        _original(d, scope, p, r, recordHash, revision, chunked);
        raw = StreamFinalityRouterEvidence.read(
            d.snapshots,
            abi.encodeCall(
                IStreamCollectionSnapshots.requireCurrent,
                (scope.collectionId, recordHash, revision)
            ),
            672,
            d.validationGas
        );
        if (keccak256(raw) != keccak256(abi.encode(r))) revert InvalidSnapshotEvidence();
        (bool locked, bytes32 locksHash) = _locks(d, r);
        e = StreamFinalitySnapshotEvidence(
            0,
            recordHash,
            r.manifestHash,
            r.sourceHash,
            r.inventoryPlan,
            r.schemaDefinitionHash,
            r.profileDefinitionHash,
            r.canonicalizationDefinitionHash,
            revision,
            r.manifestBytes,
            r.publisher,
            r.authorizationClass,
            r.grantRevision,
            r.displayAuthorizationClass,
            r.displayGrantRevision,
            locked,
            locksHash
        );
        e.inputHash = keccak256(
            abi.encode(
                chunked
                    ? keccak256("6529STREAM_FINALITY_CHUNKED_SNAPSHOT_INPUT_V1")
                    : keccak256("6529STREAM_FINALITY_NATIVE_SNAPSHOT_INPUT_V1"),
                d.chainId,
                d.core,
                d.metadata,
                d.snapshots,
                d.snapshotsCodeHash,
                scope,
                e
            )
        );
    }

    function requireLocked(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        bytes32 recordHash,
        uint64 revision
    ) public view returns (StreamFinalitySnapshotEvidence memory e) {
        e = requireCurrent(d, scope, recordHash, revision);
        if (!e.locked) revert InvalidSnapshotEvidence();
    }

    function _original(
        Dependencies memory d,
        StreamFinalityScope memory scope,
        StreamSnapshotTypes.Publication memory p,
        StreamSnapshotTypes.Receipt memory r,
        bytes32 recordHash,
        uint64 revision,
        bool chunked
    ) private pure {
        if (
            r.recordHash != recordHash || r.collectionId != scope.collectionId
                || p.collectionId != r.collectionId || r.revision != revision
                || r.revision != p.expectedRevision + 1 || r.predecessor != p.expectedHead
                || r.snapshotId == 0 || r.snapshotId != p.snapshotId || r.manifestHash == 0
                || r.manifestBytes == 0 || r.manifestBytes > (chunked ? 3000000 : 524288)
                || r.sourceHash == 0 || r.sourceHash != p.expectedSourceHash || r.inventoryPlan == 0
                || r.inventoryPlan != p.inventoryPlan || r.publisher == address(0)
                || (r.authorizationClass != 7 && r.authorizationClass != 8)
                || (r.displayAuthorizationClass != 7 && r.displayAuthorizationClass != 8)
                || r.grantRevision == 0 || r.displayGrantRevision == 0 || r.recordedAt == 0
                || r.effectiveAt == 0 || r.effectiveAt != p.effectiveAt
                || r.effectiveAt > r.recordedAt || r.reasonHash == 0 || r.reasonHash != p.reasonHash
                || r.recordChainHash == 0 || bytes(p.manifestURI).length > 2048
                || r.schemaDefinitionHash
                    != (chunked
                            ? ChunkedDefinitions.SCHEMA_HASH
                            : StreamSnapshotDefinitions.SCHEMA_HASH)
                || r.profileDefinitionHash
                    != (chunked
                            ? ChunkedDefinitions.PROFILE_HASH
                            : StreamSnapshotDefinitions.PROFILE_HASH)
                || r.canonicalizationDefinitionHash
                    != (chunked
                            ? ChunkedDefinitions.CANON_HASH
                            : StreamSnapshotDefinitions.CANON_HASH)
        ) {
            revert InvalidSnapshotEvidence();
        }
        bytes32 savedHash = r.recordHash;
        bytes32 savedChain = r.recordChainHash;
        r.recordHash = 0;
        r.recordChainHash = 0;
        bytes32 computed = keccak256(
            abi.encode(
                chunked
                    ? keccak256("6529STREAM_CHUNKED_SNAPSHOT_RECORD_V1")
                    : keccak256("6529STREAM_NATIVE_SNAPSHOT_RECORD_V1"),
                d.chainId,
                d.snapshots,
                d.core,
                d.metadata,
                p,
                r
            )
        );
        r.recordHash = savedHash;
        r.recordChainHash = savedChain;
        if (computed != recordHash) revert InvalidSnapshotEvidence();
    }

    function _locks(Dependencies memory d, StreamSnapshotTypes.Receipt memory r)
        private
        view
        returns (bool locked, bytes32 hash)
    {
        bytes32[3] memory ids = [
            keccak256("SNAPSHOTS"), keccak256("METADATA_ALL"), keccak256("SNAPSHOT_NATIVE_ONCHAIN")
        ];
        StreamSnapshotTypes.Lock[3] memory rows;
        for (uint256 i; i < 3; ++i) {
            bytes memory raw = StreamFinalityRouterEvidence.read(
                d.snapshots,
                abi.encodeCall(IStreamCollectionSnapshots.snapshotLock, (r.collectionId, ids[i])),
                128,
                d.readGas
            );
            rows[i] = abi.decode(raw, (StreamSnapshotTypes.Lock));
            _canonical(raw, abi.encode(rows[i]));
            if (rows[i].actionId == 0) {
                if (rows[i].recordHash != 0 || rows[i].revision != 0 || rows[i].lockedAt != 0) {
                    revert InvalidSnapshotEvidence();
                }
            } else {
                if (
                    rows[i].recordHash != r.recordHash || rows[i].revision != r.revision
                        || rows[i].lockedAt < r.recordedAt
                ) revert InvalidSnapshotEvidence();
                locked = true;
            }
        }
        hash = keccak256(
            abi.encode(
                keccak256("6529STREAM_FINALITY_NATIVE_SNAPSHOT_LOCKS_V1"),
                d.chainId,
                d.snapshots,
                r.collectionId,
                r.recordHash,
                r.revision,
                ids,
                rows
            )
        );
    }

    function _word(Dependencies memory d, bytes memory input) private view returns (bytes32) {
        return abi.decode(
            StreamFinalityRouterEvidence.read(d.snapshots, input, 32, d.readGas), (bytes32)
        );
    }

    function _pin(address target, bytes32 codeHash) private view {
        if (target.code.length == 0 || codeHash == 0 || target.codehash != codeHash) {
            revert InvalidSnapshotEvidence();
        }
    }

    function _canonical(bytes memory a, bytes memory b) private pure {
        if (a.length != b.length || keccak256(a) != keccak256(b)) revert InvalidSnapshotEvidence();
    }
}

