                ? keccak256("6529STREAM_SCOPED_PRESERVATION_POLICY_CONTENT_ROOT_STATE_V2")
                : keccak256("6529STREAM_PRESERVATION_POLICY_CONTENT_ROOT_STATE_V2");
        }
