// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";
import {
    IStreamCollectionMetadataV1 as M
} from "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";

interface IStreamMetadataArtistConfiguration {
    function suiteConfiguration() external view returns (T.SuiteConfiguration memory);
    function configurationHash() external view returns (bytes32);
    function finalityRegistry() external view returns (address);
    function finalityEvidenceProvider() external view returns (address);
}

/// @notice Authenticates the actual original Coordinator constructor commitment.
/// @dev The preimage is byte-exact to StreamArtistOnboardingCoordinator's original
/// configurationHash. Live target hashes retain all16 runtime pins without reading
/// duplicate stored target/hash arrays. No new Coordinator API or gas cap is used.
library StreamMetadataArtistConfiguration {
    function suite(address coordinator, uint256 cap)
        public
        view
        returns (T.SuiteConfiguration memory s)
    {
        bytes memory raw = _read(
            coordinator, IStreamMetadataArtistConfiguration.suiteConfiguration.selector, 544, cap
        );
        s = abi.decode(raw, (T.SuiteConfiguration));
        if (keccak256(raw) != keccak256(abi.encode(s))) revert M.MetadataHostNotSelected();
        address finality = abi.decode(
            _read(
                coordinator, IStreamMetadataArtistConfiguration.finalityRegistry.selector, 32, cap
            ),
            (address)
        );
        address provider = abi.decode(
            _read(
                coordinator,
                IStreamMetadataArtistConfiguration.finalityEvidenceProvider.selector,
                32,
                cap
            ),
            (address)
        );
        bytes32 actual = abi.decode(
            _read(
                coordinator, IStreamMetadataArtistConfiguration.configurationHash.selector, 32, cap
            ),
            (bytes32)
        );
        if (
            finality.code.length == 0 || provider.code.length == 0
                || actual != hash(coordinator, s, finality, provider)
        ) revert M.MetadataHostNotSelected();
    }

    function hash(
        address coordinator,
        T.SuiteConfiguration memory suite,
        address finality,
        address provider
    ) internal view returns (bytes32) {
        (bytes32 result,) = hashAndRuntime(coordinator, suite, finality, provider);
        return result;
    }

    /// @dev Return the runtime facts authenticated by the original constructor hash so a
    /// fixed caller can reuse them without a second set of code reads. Same encoding/checks.
    function hashAndRuntime(
        address coordinator,
        T.SuiteConfiguration memory suite,
        address finality,
        address provider
    ) internal view returns (bytes32 result, bytes32[16] memory runtimeHashes) {
        address[16] memory targets;
        for (uint256 i; i < 7; ++i) {
            targets[i] = suite.owners[i];
        }
        targets[7] = suite.registry;
        targets[8] = suite.archive;
        targets[9] = suite.core;
        targets[10] = suite.mintManager;
        targets[11] = suite.roleRegistry;
        targets[12] = suite.metadata;
        targets[13] = suite.primaryResolver;
        targets[14] = suite.royaltyResolver;
        targets[15] = suite.validator;
        for (uint256 i; i < 16; ++i) {
            if (targets[i].code.length == 0) revert M.MetadataHostNotSelected();
            runtimeHashes[i] = targets[i].codehash;
        }
        bytes32 providerCodeHash = provider.codehash;
        result = keccak256(
            abi.encode(
                keccak256("6529STREAM_ARTIST_ONBOARDING_CONFIGURATION_V1"),
                block.chainid,
                coordinator,
                suite,
                runtimeHashes,
                finality,
                finality.codehash,
                provider,
                providerCodeHash,
                uint16(1),
                uint16(2),
                uint16(3),
                uint16(4),
                uint16(5),
                uint16(6),
                uint16(7),
                uint16(12),
                uint16(13),
                uint16(14),
                uint16(15),
                uint16(16),
                uint16(17),
                uint16(18),
                uint16(20),
                uint16(21),
                uint16(22),
                uint16(23),
                uint16(24),
                uint16(25),
                uint16(26),
                uint16(27),
                uint16(28),
                uint16(29),
                uint16(30),
                uint16(31),
                uint16(32),
                uint16(33),
                uint16(34),
                uint16(35),
                uint16(36),
                uint16(37),
                uint16(38),
                uint16(39),
                uint16(40),
                uint16(51),
                uint16(52),
                uint16(54),
                uint16(58),
                uint16(65534),
                keccak256("6529STREAM_ARTIST_RECOVERY_PREPARATION_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_RECOVERY_GUARDIAN_HISTORY_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_RECOVERY_FIRST_ROTATION_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_RECOVERY_HISTORICAL_ROTATION_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_GUARDIAN_VESTING_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_GUARDIAN_SUPERSESSION_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_GUARDIAN_HEAD_SELECTION_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_GUARDIAN_ROOT_APPEAL_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_FIRST_ESTATE_RECOVERY_PROFILE_V1"),
                keccak256("6529STREAM_ARTIST_ESTATE_SUCCESSOR_GUARDIAN_RECOVERY_PROFILE_V1")
            )
        );
    }

    function _read(address target, bytes4 selector, uint256 length, uint256 cap)
        private
        view
        returns (bytes memory data)
    {
        if (
            target.code.length == 0 || cap == 0 || cap == type(uint256).max
                || gasleft() <= cap + cap / 63 + 10000
        ) revert M.MetadataReadFailed(target);
        data = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            mstore(ptr, selector)
            ok := staticcall(cap, target, ptr, 4, add(data, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) revert M.MetadataReadFailed(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { IStreamCorePointers } from "../../interfaces/stream/core/IStreamCorePointers.sol";
import {
    IStreamCollectionMetadataV1 as M
} from "../../interfaces/stream/metadata/IStreamCollectionMetadataV1.sol";
import { IStreamArtistHistory } from "../../interfaces/stream/artist/IStreamArtistHistory.sol";
import {
    IStreamArtistIngressBinding
} from "../../interfaces/stream/artist/IStreamArtistIngressBinding.sol";
import { IStreamArtistOwner } from "../../interfaces/stream/artist/IStreamArtistOwner.sol";
import {
    IStreamArtistAuthorityHydrationCoordinator,
    IStreamArtistAuthorityHydrationOwner
} from "../../interfaces/stream/artist/IStreamArtistAuthorityHydration.sol";
import {
    StreamArtistOnboardingTypes as T
} from "../../interfaces/stream/artist/StreamArtistOnboardingTypes.sol";

import { StreamMetadataArtistConfiguration } from "./StreamMetadataArtistConfiguration.sol";
import {
    StreamMetadataRecoveredArtistSelection,
    IStreamMetadataCurrentCompletion
} from "./StreamMetadataRecoveredArtistSelection.sol";

/// @notice Same-Metadata publication through its original Artist or completely hydrated successor.
/// @dev Reads only. Metadata retains its original authorization-use map and candidate domains.
library StreamMetadataArtistSelection {
    struct Context {
        address core;
        bytes32 coreHash;
        address original;
        bytes32 originalHash;
        uint256 gasCap;
    }

    struct Selected {
        address registry;
        bytes32 runtimeHash;
    }

    function selected(Context memory c) public view returns (Selected memory s) {
        _code(c.core, c.coreHash);
        _code(c.original, c.originalHash);
        bytes memory raw = _read(
            c,
            c.core,
            abi.encodeCall(IStreamCorePointers.getSatellitePointer, (keccak256("ARTIST_REGISTRY"))),
            320
        );
        (s.registry, s.runtimeHash,,,,,,,,) = abi.decode(
            raw, (address, bytes32, bool, bytes32, bytes4, address, uint8, bytes32, bytes32, uint64)
        );
        _code(s.registry, s.runtimeHash);
        // Earlier Metadata/Artist suites need no hydration API for their original selection.
        if (s.registry == c.original) {
            if (s.runtimeHash != c.originalHash) revert M.MetadataHostNotSelected();
            return s;
        }
        (bool sourceSealed, address successor, uint64 sealedAt) = abi.decode(
            _read(
                c, c.original, abi.encodeCall(IStreamArtistHistory.artistRegistryCutover, ()), 96
            ),
            (bool, address, uint64)
        );
        if (!sourceSealed || successor == address(0) || sealedAt == 0) {
            revert M.MetadataHostNotSelected();
        }
        if (successor == s.registry) {
            if (
                _word(
                        c,
                        s.registry,
                        abi.encodeCall(IStreamArtistHistory.importedHistoryBindingCount, ())
                    ) != 1
            ) revert M.MetadataHostNotSelected();
            (address predecessor, uint64 snapshot, bytes32 root, bytes32 manifest) = abi.decode(
                _read(
                    c,
                    s.registry,
                    abi.encodeCall(IStreamArtistHistory.importedHistoryBinding, (0)),
                    128
                ),
                (address, uint64, bytes32, bytes32)
            );
            (bool bound, bytes32 sourceHash, uint256 count) = abi.decode(
                _read(
                    c,
                    s.registry,
                    abi.encodeCall(
                        IStreamArtistHistory.artistHistoryPredecessorBinding, (c.original)
                    ),
                    96
                ),
                (bool, bytes32, uint256)
            );
            if (
                predecessor != c.original || snapshot == 0 || snapshot > sealedAt || root == 0
                    || manifest == 0 || !bound || sourceHash != c.originalHash || count != 1
            ) revert M.MetadataHostNotSelected();
        }
        (address nextCoordinator, T.SuiteConfiguration memory next) = _suite(c, s.registry);
        address priorCoordinator;
        if (successor != s.registry) {
            priorCoordinator = abi.decode(
                _read(
                    c,
                    address(StreamMetadataRecoveredArtistSelection),
                    abi.encodeCall(
                        IStreamMetadataCurrentCompletion.repeatedAncestor,
                        (c.core, c.original, s.registry, abi.encode(next))
                    ),
                    32
                ),
                (address)
            );
        } else {
            priorCoordinator = abi.decode(
                _read(
                    c,
                    c.original,
                    abi.encodeCall(IStreamArtistIngressBinding.operationCoordinator, ()),
                    32
                ),
                (address)
            );
        }
        if (priorCoordinator == address(0) || priorCoordinator == nextCoordinator) {
            revert M.MetadataHostNotSelected();
        }
        // The repeated branch already authenticated this same fixed Router/owner proof.
        if (successor != s.registry) return s;
        // All actual op60 profiles share Source._prepare/SourceGuards._suite and
        // Commit.execute: the exact sealed predecessor, all eight unchanged suite
        // dependencies, and each source owner's reciprocal binding/domain are
        // checked before the seven owner imports, then rechecked before atomic
        // Archive completion. The one-time marker below has no other producer.
        // Both suites/owner bindings are constructor-only. Thus committed op60
        // proves the original relationship without a live read of its old suite.
        // This is committed-state provenance, not an in-flight reentrancy barrier.
        // Artist's metadata dependency is the rendering Router, not this record host.
        (address router, bytes32 routerHash,,,,,,,,) = abi.decode(
            _read(
                c,
                c.core,
                abi.encodeCall(
                    IStreamCorePointers.getSatellitePointer, (keccak256("METADATA_ROUTER"))
                ),
                320
            ),
            (address, bytes32, bool, bytes32, bytes4, address, uint8, bytes32, bytes32, uint64)
        );
        if (router != next.metadata) revert M.MetadataHostNotSelected();
        _code(router, routerHash);
        if (
            abi.decode(_read(c, router, abi.encodeCall(IStreamArtistOwner.core, ()), 32), (address))
                != c.core
        ) revert M.MetadataHostNotSelected();
        bytes32 completion;
        for (uint256 i; i < 7; ++i) {
            // The current authentic Coordinator constructor validates all seven
            // immutable owner bindings and distinct targets; _suite above rechecks
            // every saved runtime pin. Different source/next registry bindings
            // prohibit sharing an owner. Keep every actual completion check.
            bytes32 actual = bytes32(
                _word(
                    c,
                    next.owners[i],
                    abi.encodeCall(
                        IStreamArtistAuthorityHydrationOwner.authorityHydrationCommitment, ()
                    )
                )
            );
            if (actual == 0 || (i != 0 && actual != completion)) {
                revert M.MetadataHostNotSelected();
            }
            completion = actual;
        }
    }

    function _suite(Context memory c, address registry)
        private
        view
        returns (address coordinator, T.SuiteConfiguration memory s)
    {
        coordinator = abi.decode(
            _read(
                c,
                registry,
                abi.encodeCall(IStreamArtistIngressBinding.operationCoordinator, ()),
                32
            ),
            (address)
        );
        s = StreamMetadataArtistConfiguration.suite(coordinator, c.gasCap);
        if (
            s.registry != registry || s.core != c.core || s.metadata == address(0)
                || s.archive.code.length == 0 || s.mintManager == address(0)
        ) revert M.MetadataHostNotSelected();
    }

    function _word(Context memory c, address target, bytes memory input)
        private
        view
        returns (uint256)
    {
        return abi.decode(_read(c, target, input, 32), (uint256));
    }

    function _code(address target, bytes32 expected) private view {
        if (target.code.length == 0 || target.codehash != expected) {
            revert M.MetadataDependencyChanged(target);
        }
    }

    // Host-owned dependency budget; fixed responses never allocate from returned data.
    function _read(Context memory c, address target, bytes memory input, uint256 length)
        private
        view
        returns (bytes memory data)
    {
        uint256 cap = c.gasCap;
        if (
            target.code.length == 0 || cap == 0 || cap == type(uint256).max
                || gasleft() <= cap + cap / 63 + 10000
        ) revert M.MetadataReadFailed(target);
        data = new bytes(length);
        bool ok;
        uint256 size;
        assembly ("memory-safe") {
            ok := staticcall(cap, target, add(input, 32), mload(input), add(data, 32), length)
            size := returndatasize()
        }
        if (!ok || size != length) revert M.MetadataReadFailed(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import { Strings } from "../../vendor/openzeppelin/Strings.sol";

/// @notice Canonical work identity only; no record-state or authority claim is inferred.
library StreamMetadataCitation {
    function work(uint256 originalChainId, address originalCore, uint256 globalTokenId)
        internal
        pure
        returns (string memory)
    {
        return string.concat(
            "eip155:",
            Strings.toString(originalChainId),
            "/erc721:",
            Strings.toHexString(uint256(uint160(originalCore)), 20),
            "/",
            Strings.toString(globalTokenId)
        );
    }

    /// @dev Input is the fixed encoder's own complete object, never caller JSON.
    function inObject(string memory object, string memory citation)
        internal
        pure
        returns (string memory)
    {
        bytes memory encoded = bytes(object);
        assert(encoded.length >= 2 && encoded[encoded.length - 1] == 0x7d);
        assembly ("memory-safe") { mstore(encoded, sub(mload(encoded), 1)) }
        return string(bytes.concat(encoded, bytes(',"citation":"'), bytes(citation), bytes('"}')));
    }
}

