library StreamPreservationPolicyReferenceFamiliesV2 {
    struct Definition {
        bytes32 schemaId;
        bytes32 profileId;
        bytes32 canonId;
        bytes32 schemaHash;
        bytes32 profileHash;
        bytes32 canonHash;
        uint32 schemaBytes;
        uint32 profileBytes;
        uint32 canonBytes;
    }
    error InvalidPreservationReferenceFamily();

    function isV2(bytes32 family) internal pure returns (bool) {
        if (family != P.ORIGINAL_PROFILE && family != P.FAMILY_PROFILE) {
            revert InvalidPreservationReferenceFamily();
        }
        return family == P.FAMILY_PROFILE;
    }

    function definition(bytes32 family, bool scoped) internal pure returns (Definition memory) {
        if (isV2(family)) {
            if (scoped) {
                return Definition(
                    S2.SCHEMA_ID,
                    S2.PROFILE_ID,
                    S2.CANON_ID,
                    S2.SCHEMA_HASH,
                    S2.PROFILE_HASH,
                    S2.CANON_HASH,
                    S2.SCHEMA_BYTES,
                    S2.PROFILE_BYTES,
                    S2.CANON_BYTES
                );
            }
            return Definition(
                C2.SCHEMA_ID,
                C2.PROFILE_ID,
                C2.CANON_ID,
                C2.SCHEMA_HASH,
                C2.PROFILE_HASH,
                C2.CANON_HASH,
                C2.SCHEMA_BYTES,
                C2.PROFILE_BYTES,
                C2.CANON_BYTES
            );
        }
        if (scoped) {
            return Definition(
                S1.SCHEMA_ID,
                S1.PROFILE_ID,
                S1.CANON_ID,
                S1.SCHEMA_HASH,
                S1.PROFILE_HASH,
                S1.CANON_HASH,
                S1.SCHEMA_BYTES,
                S1.PROFILE_BYTES,
                S1.CANON_BYTES
            );
        }
        return Definition(
            C1.SCHEMA_ID,
            C1.PROFILE_ID,
            C1.CANON_ID,
            C1.SCHEMA_HASH,
            C1.PROFILE_HASH,
            C1.CANON_HASH,
            C1.SCHEMA_BYTES,
            C1.PROFILE_BYTES,
            C1.CANON_BYTES
