    }

    function recordDomain(bytes32 family, bool scoped) internal pure returns (bytes32) {
        if (isV2(family)) {
            return scoped
                ? keccak256("6529STREAM_SCOPED_PRESERVATION_POLICY_REFERENCE_RECORD_V2")
