} from "../../interfaces/stream/metadata/IStreamTerminalEntropyRenderer.sol";

library StreamPreservationPolicyRenderCriticalProfileReadsV1 {
    bytes32 private constant PROFILE = keccak256("6529STREAM_CURRENT_BASE_CITATION_V1");
    bytes32 private constant TERMINAL = keccak256("6529STREAM_TERMINAL_ENTROPY_RENDER_V1");

    function item(S.Dependencies memory d, Scoped.Context memory c, uint64 ordinal, uint64 index)
        public
        view
        returns (T.Item memory row, uint64 count)
    {
        (uint256 token, Tokens.Original memory source) = Tokens.sourceAt(d, c, ordinal);
        Router.Selection memory selected = source.selection.selection;
        bool terminal = source.output.entropy.terminal;
        bytes32 expectedProfile = terminal ? TERMINAL : PROFILE;
        bytes4 expectedSelector =
            terminal ? TerminalRenderer.renderTerminal.selector : Renderer.renderCurrent.selector;
        IO.pin(selected.registry, selected.registryCodeHash);
        IO.pin(selected.renderer, selected.rendererCodeHash);
        bytes memory raw = IO.fixedRead(
            selected.renderer,
            abi.encodeCall(
                IERC165.supportsInterface,
                (terminal ? type(TerminalRenderer).interfaceId : type(Renderer).interfaceId)
            ),
            32,
            d.readGas
        );
        bool supported = abi.decode(raw, (bool));
        IO.canonical(selected.renderer, raw, abi.encode(supported));
        if (!supported) {
            if (terminal) revert T.InventorySourceChanged();
            if (index != 0) revert T.InvalidInventoryItem();
            return (
                Items.absent(
                    terminal
                        ? keccak256("TERMINAL_ENTROPY_ADMISSION")
                        : keccak256("CURRENT_BASE_CITATION_ADMISSION"),
                    selected.registry,
                    selected.versionKey,
                    token
                ),
                1
            );
        }
        count = terminal ? 8 : 5;
        if (index >= count) revert T.InvalidInventoryItem();
        raw = IO.fixedRead(
            selected.registry,
            terminal
                ? abi.encodeCall(TerminalRegistry.requireTerminalEntropy, (selected.versionKey))
                : abi.encodeCall(Registry.requireCurrentCitation, (selected.versionKey)),
            128,
            d.sourceGas
        );
        (address renderer, bytes32 runtime, bytes32 profile, bytes4 selector) =
            abi.decode(raw, (address, bytes32, bytes32, bytes4));
        IO.canonical(selected.registry, raw, abi.encode(renderer, runtime, profile, selector));
        if (
            renderer != selected.renderer || runtime != selected.rendererCodeHash
                || profile != expectedProfile || selector != expectedSelector
        ) {
            revert T.InventorySourceChanged();
        }
        raw = IO.fixedRead(
            selected.registry,
            terminal
                ? abi.encodeCall(TerminalRegistry.terminalEntropyRecord, (selected.versionKey))
                : abi.encodeCall(Registry.currentCitationRecord, (selected.versionKey)),
            384,
            d.readGas
        );
        Registry.CurrentRecord memory record = abi.decode(raw, (Registry.CurrentRecord));
        IO.canonical(selected.registry, raw, abi.encode(record));
        Registry.CurrentRegistration memory r = record.registration;
        if (
            r.versionKey != selected.versionKey || r.profile != expectedProfile
                || r.selector != selector || record.actionId == 0 || record.analysisHash == 0
                || record.goldenHash == 0
        ) revert T.InventorySourceChanged();
        IO.pin(r.encoding, r.encodingRuntimeHash);
        bytes memory binding = IO.fixedRead(
            renderer,
            terminal
                ? abi.encodeCall(TerminalRenderer.terminalEncodingBinding, ())
                : abi.encodeCall(Renderer.encodingBinding, ()),
            64,
            d.readGas
        );
        IO.canonical(renderer, binding, abi.encode(r.encoding, r.encodingRuntimeHash));
        bytes memory declared = IO.read(
            selected.registry,
            terminal
                ? abi.encodeCall(TerminalRegistry.terminalEntropyReads, (selected.versionKey))
                : abi.encodeCall(Registry.currentCitationReads, (selected.versionKey)),
            16448,
            d.readGas
        );
        V.Read[] memory reads = abi.decode(declared, (V.Read[]));
        IO.canonical(selected.registry, declared, abi.encode(reads));
        _reads(d, selected, record, reads, terminal);
        if (terminal) {
            T.Item memory extra = _terminal(d, source, record, token, index);
            if (index >= 5) return (extra, count);
        }
        if (index == 0) {
            return (
                Items.bytesItem(
                    T.Kind.NATIVE_BYTES,
                    terminal
                        ? keccak256("TERMINAL_ENTROPY_ADMISSION")
                        : keccak256("CURRENT_BASE_CITATION_ADMISSION"),
                    selected.registry,
                    selected.versionKey,
                    token,
                    raw
                ),
                count
            );
        }
        if (index == 1) {
            return (
                Items.bytesItem(
                    T.Kind.NATIVE_BYTES,
                    terminal
                        ? keccak256("TERMINAL_ENTROPY_READS")
                        : keccak256("CURRENT_BASE_CITATION_READS"),
                    selected.registry,
                    selected.versionKey,
                    token,
                    declared
                ),
                count
            );
        }
        if (index == 2) return (Documents.item(d, r.analysisDocument, record.analysisHash), count);
        if (index == 3) return (Documents.item(d, r.goldenDocument, record.goldenHash), count);
        return (
            Items.runtime(
                terminal
                    ? keccak256("TERMINAL_ENTROPY_ENCODING")
                    : keccak256("CURRENT_BASE_CITATION_ENCODING"),
                r.encoding,
                record.registrationHash,
                token
            ),
            count
        );
    }

    function _terminal(
        S.Dependencies memory d,
        Tokens.Original memory source,
        Registry.CurrentRecord memory record,
        uint256 token,
        uint64 index
    ) private view returns (T.Item memory row) {
        address renderer = source.selection.selection.renderer;
        bytes memory validation = IO.fixedRead(
            renderer, abi.encodeCall(TerminalRenderer.terminalValidationBinding, ()), 64, d.readGas
        );
        (address validator, bytes32 runtime) = abi.decode(validation, (address, bytes32));
        IO.canonical(renderer, validation, abi.encode(validator, runtime));
        IO.pin(validator, runtime);
        bytes memory policy = IO.fixedRead(
            renderer, abi.encodeCall(TerminalRenderer.terminalPolicyBinding, ()), 96, d.readGas
        );
        (address core, address coordinator, bytes32 coordinatorHash) =
            abi.decode(policy, (address, address, bytes32));
        IO.canonical(renderer, policy, abi.encode(core, coordinator, coordinatorHash));
        if (
            core != d.targets[0] || coordinator != source.selection.sources[3]
                || coordinatorHash != source.selection.sourceCodeHashes[3]
        ) revert T.InventorySourceChanged();
        IO.pin(coordinator, coordinatorHash);
        if (index == 5) {
            return Items.bytesItem(
                T.Kind.NATIVE_BYTES,
                keccak256("TERMINAL_VALIDATION_BINDING"),
                renderer,
                record.registrationHash,
                token,
                validation
            );
        }
        if (index == 6) {
            return Items.runtime(
                keccak256("TERMINAL_VALIDATION_RUNTIME"), validator, record.registrationHash, token
            );
        }
        if (index == 7) {
            return Items.bytesItem(
                T.Kind.NATIVE_BYTES,
                keccak256("TERMINAL_POLICY_BINDING"),
                renderer,
                record.registrationHash,
                token,
                policy
            );
        }
    }

    function _reads(
        S.Dependencies memory d,
        Router.Selection memory selected,
        Registry.CurrentRecord memory record,
        V.Read[] memory reads,
        bool terminal
    ) private view {
        address registry = selected.registry;
        if (
            IO.addressWord(registry, abi.encodeWithSignature("schemaRegistry()"), d.readGas)
                    != d.targets[2]
                || IO.word(registry, abi.encodeWithSignature("schemaRegistryCodeHash()"), d.readGas)
                    != d.codeHashes[2]
                || uint256(
                        IO.word(registry, abi.encodeWithSignature("deploymentChainId()"), d.readGas)
                    ) != d.chainId
        ) {
            revert T.InventorySourceChanged();
        }
        bytes32 targetsHash =
            IO.word(registry, abi.encodeWithSignature("targetSetHash()"), d.readGas);
        if (
            keccak256(abi.encode(keccak256("6529STREAM_RENDERER_READ_SET_V1"), targetsHash, reads))
                    != record.readSetHash
                || keccak256(
                        abi.encode(
                            terminal
                                ? keccak256("6529STREAM_TERMINAL_ENTROPY_REGISTRATION_V1")
                                : keccak256("6529STREAM_CURRENT_CITATION_REGISTRATION_V1"),
                            d.chainId,
                            registry,
                            d.targets[2],
                            d.codeHashes[2],
                            targetsHash,
                            selected.registrationHash,
                            record.registration,
                            reads
                        )
                    ) != record.registrationHash
        ) {
            revert T.InventorySourceChanged();
        }
        bytes memory raw =
            IO.read(registry, abi.encodeCall(V.reads, (selected.versionKey)), 16448, d.readGas);
        V.Read[] memory original = abi.decode(raw, (V.Read[]));
        IO.canonical(registry, raw, abi.encode(original));
        if (reads.length > 128 || original.length > reads.length) revert T.InvalidInventoryItem();
        uint256 n = uint256(IO.word(registry, abi.encodeCall(V.targetCount, ()), d.readGas));
        if (n == 0 || n > 64) revert T.InvalidInventoryItem();
        uint256 previous;
        uint256 cursor;
        for (uint256 i; i < reads.length; ++i) {
            V.Read memory r = reads[i];
            uint256 order = (uint256(r.targetIndex) << 32) | uint32(r.selector);
            if (
                r.targetIndex >= n || r.selector == 0 || (i != 0 && order <= previous)
                    || r.maxReturnBytes == 0 || r.maxReturnBytes > 16777216
                    || (r.exact && r.maxReturnBytes % 32 != 0)
            ) {
                revert T.InvalidInventoryItem();
            }
            previous = order;
            if (
                cursor < original.length
                    && keccak256(abi.encode(r)) == keccak256(abi.encode(original[cursor]))
            ) ++cursor;
        }
        if (cursor != original.length) revert T.InventorySourceChanged();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamRenderCriticalSourceTypes as S
} from "../../interfaces/stream/preservation/StreamRenderCriticalSourceTypes.sol";
import {
    StreamPreservationPolicyRenderCriticalTypesV1 as Scoped
} from "../../interfaces/stream/preservation/StreamPreservationPolicyRenderCriticalTypesV1.sol";
import {
    StreamPreservationInventoryTypes as T
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import {
    IStreamRendererRegistry as V
} from "../../interfaces/stream/metadata/IStreamRendererRegistry.sol";
import { IStreamRenderer as R } from "../../interfaces/stream/metadata/IStreamRenderer.sol";
import {
    IStreamStaticMetadataRouter as Router
} from "../../interfaces/stream/metadata/IStreamStaticMetadataRouter.sol";
import {
    StreamPreservationPolicyRenderCriticalTokenReadsV1 as Tokens
} from "./StreamPreservationPolicyRenderCriticalTokenReadsV1.sol";
import { StreamPreservationInventoryIO as IO } from "./StreamPreservationInventoryIO.sol";
import { StreamPreservationInventoryItems as Items } from "./StreamPreservationInventoryItems.sol";
import {
    StreamPreservationDocumentReads as Documents
} from "./StreamPreservationDocumentReads.sol";

/// @notice Original retained renderer declaration, complete named target roster and five documents.
/// @dev This worker does not claim transitive opcode conformance. A separately admitted current
/// output profile also requires its own declaration/analysis/goldens/read-set inventory.
library StreamPreservationPolicyRenderCriticalRendererReadsV1 {
    struct Original {
        Router.Selection selected;
        V.Version version;
        V.Registration registration;
        V.Read[] reads;
        V.Target[] targets;
        bytes bindings;
        address encoding;
        bytes32 encodingHash;
    }

    function item(S.Dependencies memory d, Scoped.Context memory c, uint64 ordinal, uint64 index)
        public
        view
        returns (T.Item memory row, uint64 count)
    {
        (uint256 token, Tokens.Original memory source) = Tokens.sourceAt(d, c, ordinal);
        Original memory o = _load(d, source.selection.selection, source.selection.sources[3]);
        count = uint64(13 + o.targets.length);
        if (index >= count) revert T.InvalidInventoryItem();
        address registry = o.selected.registry;
        bytes32 key = o.selected.versionKey;
        if (index == 0) {
            return (
                _bytes("RENDERER_RETAINED_VERSION", registry, key, token, abi.encode(o.version)),
                count
            );
        }
        if (index == 1) {
            return (
                _bytes("RENDERER_REGISTRATION", registry, key, token, abi.encode(o.registration)),
                count
            );
        }
        if (index == 2) {
            return
                (
                    _bytes("RENDERER_DECLARED_READS", registry, key, token, abi.encode(o.reads)),
                    count
                );
        }
        if (index == 3) {
            return (
                _bytes("RENDERER_COMPLETE_TARGETS", registry, key, token, abi.encode(o.targets)),
                count
            );
        }
        if (index == 4) {
            return
                (Items.runtime(keccak256("RENDERER_REGISTRY_RUNTIME"), registry, key, token), count);
        }
        if (index == 5) {
            return (
                Items.runtime(
                    keccak256("SELECTED_RENDERER_RUNTIME"), o.selected.renderer, key, token
                ),
                count
            );
        }
        if (index == 6) {
            return (
                _bytes("RENDERER_SOURCE_BINDINGS", o.selected.renderer, key, token, o.bindings),
                count
            );
        }
        if (index == 7) {
            return (
                Items.runtime(keccak256("RENDERER_ENCODING_RUNTIME"), o.encoding, key, token), count
            );
        }
        if (index < 13) {
            bytes32[5] memory ids = [
                o.registration.schemaDocument,
                o.registration.contextDocument,
                o.registration.manifestDocument,
                o.registration.analysisDocument,
                o.registration.goldenDocument
            ];
            bytes32[5] memory hashes = [
                o.registration.manifest.schemaHash,
                bytes32(0),
                o.registration.manifest.manifestHash,
                o.version.analysisHash,
                o.version.goldenHash
            ];
            row = Documents.item(d, ids[index - 8], hashes[index - 8]);
            return (row, count);
        }
        V.Target memory target = o.targets[index - 13];
        row = Items.runtime(target.role, target.target, key, index - 13);
        row.provenanceHash = keccak256(abi.encode(registry, key, target));
    }

    function _load(S.Dependencies memory d, Router.Selection memory selected, address coordinator)
        private
        view
        returns (Original memory o)
    {
        o.selected = selected;
        address registry = selected.registry;
        IO.pin(registry, selected.registryCodeHash);
        IO.pin(selected.renderer, selected.rendererCodeHash);
        if (
            IO.addressWord(registry, abi.encodeWithSignature("schemaRegistry()"), d.readGas)
                    != d.targets[2]
                || IO.word(registry, abi.encodeWithSignature("schemaRegistryCodeHash()"), d.readGas)
                    != d.codeHashes[2]
                || uint256(
                        IO.word(registry, abi.encodeWithSignature("deploymentChainId()"), d.readGas)
                    ) != d.chainId
        ) {
            revert T.InventorySourceChanged();
        }
        bytes memory raw = IO.fixedRead(
            registry, abi.encodeCall(V.version, (selected.versionKey)), 288, d.readGas
        );
        o.version = abi.decode(raw, (V.Version));
        IO.canonical(registry, raw, abi.encode(o.version));
        if (
            !o.version.exists || o.version.renderer != selected.renderer
                || o.version.runtimeHash != selected.rendererCodeHash
                || o.version.registrationHash != selected.registrationHash
                || o.version.readSetHash != selected.readSetHash
        ) {
            revert T.InventorySourceChanged();
        }
        // Deprecated immutable versions remain retained; ordinary new-assignment policy is separate.
        raw = IO.fixedRead(
            registry, abi.encodeCall(V.requireRetained, (selected.versionKey)), 64, d.sourceGas
        );
        (address retained, bytes32 retainedHash) = abi.decode(raw, (address, bytes32));
        IO.canonical(registry, raw, abi.encode(retained, retainedHash));
        if (retained != selected.renderer || retainedHash != selected.rendererCodeHash) {
            revert T.InventorySourceChanged();
        }
        raw = IO.read(
            registry, abi.encodeCall(V.registration, (selected.versionKey)), 8192, d.readGas
        );
        o.registration = abi.decode(raw, (V.Registration));
        IO.canonical(registry, raw, abi.encode(o.registration));
        R.RendererManifest memory m = o.registration.manifest;
        if (
            o.registration.renderer != selected.renderer || m.rendererId != selected.rendererId
                || m.rendererVersion != selected.rendererVersion
                || m.contextVersion != selected.contextVersion
                || m.schemaHash != selected.schemaHash || m.rendererClass != keccak256("STATIC")
                || selected.versionKey
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_RENDERER_VERSION_V1"),
                            m.rendererId,
                            m.rendererVersion
                        )
                    )
        ) {
            revert T.InventorySourceChanged();
        }
        raw = IO.read(selected.renderer, abi.encodeCall(R.rendererManifest, ()), 8192, d.readGas);
        IO.canonical(selected.renderer, raw, abi.encode(m));
        raw = IO.read(registry, abi.encodeCall(V.reads, (selected.versionKey)), 16448, d.readGas);
        o.reads = abi.decode(raw, (V.Read[]));
        IO.canonical(registry, raw, abi.encode(o.reads));
        uint256 n = uint256(IO.word(registry, abi.encodeCall(V.targetCount, ()), d.readGas));
        if (n == 0 || n > 64 || o.reads.length > 128) revert T.InvalidInventoryItem();
        o.targets = new V.Target[](n);
        for (uint256 i; i < n; ++i) {
            raw = IO.fixedRead(registry, abi.encodeCall(V.targetAt, (i)), 96, d.readGas);
            o.targets[i] = abi.decode(raw, (V.Target));
            IO.canonical(registry, raw, abi.encode(o.targets[i]));
            if (i != 0 && o.targets[i].target <= o.targets[i - 1].target) {
                revert T.InvalidInventoryItem();
            }
            IO.pin(o.targets[i].target, o.targets[i].codeHash);
        }
        bytes32 targetsHash = keccak256(abi.encode(o.targets));
        if (
            targetsHash != IO.word(registry, abi.encodeWithSignature("targetSetHash()"), d.readGas)
                || keccak256(
                        abi.encode(
                            keccak256("6529STREAM_RENDERER_READ_SET_V1"), targetsHash, o.reads
                        )
                    ) != selected.readSetHash
                || keccak256(
                        abi.encode(
                            keccak256("6529STREAM_RENDERER_REGISTRATION_V1"),
                            d.chainId,
                            registry,
                            d.targets[2],
                            d.codeHashes[2],
                            targetsHash,
                            o.registration,
                            o.reads
                        )
                    ) != selected.registrationHash
        ) {
            revert T.InventorySourceChanged();
        }
        uint256 previous;
        for (uint256 i; i < o.reads.length; ++i) {
            V.Read memory declared = o.reads[i];
            uint256 order = (uint256(declared.targetIndex) << 32) | uint32(declared.selector);
            if (
                declared.targetIndex >= n || declared.selector == 0 || (i != 0 && order <= previous)
                    || declared.maxReturnBytes == 0 || declared.maxReturnBytes > 16777216
                    || (declared.exact && declared.maxReturnBytes % 32 != 0)
            ) revert T.InvalidInventoryItem();
            previous = order;
        }
        o.bindings = IO.fixedRead(
            selected.renderer, abi.encodeWithSignature("sourceBindings()"), 384, d.readGas
        );
        (address[6] memory sources, bytes32[6] memory pins) =
            abi.decode(o.bindings, (address[6], bytes32[6]));
        IO.canonical(selected.renderer, o.bindings, abi.encode(sources, pins));
        if (
            sources[0] != d.targets[0] || sources[1] != d.targets[4] || sources[2] != d.targets[1]
                || sources[3] != coordinator
        ) revert T.InventorySourceChanged();
        for (uint256 i; i < 6; ++i) {
            if (i == 4 && sources[i] == address(0)) continue;
            IO.pin(sources[i], pins[i]);
        }
        raw = IO.fixedRead(
            selected.renderer, abi.encodeWithSignature("encodingBinding()"), 64, d.readGas
        );
        (o.encoding, o.encodingHash) = abi.decode(raw, (address, bytes32));
        IO.canonical(selected.renderer, raw, abi.encode(o.encoding, o.encodingHash));
        IO.pin(o.encoding, o.encodingHash);
    }

    function _bytes(
        string memory role,
        address host,
        bytes32 record,
        uint256 token,
        bytes memory value
    ) private pure returns (T.Item memory) {
        return Items.bytesItem(
            T.Kind.NATIVE_BYTES, keccak256(bytes(role)), host, record, token, value
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamRenderCriticalSourceTypes as S
} from "../../interfaces/stream/preservation/StreamRenderCriticalSourceTypes.sol";
import {
    StreamPreservationPolicyRenderCriticalTypesV1 as Scoped
} from "../../interfaces/stream/preservation/StreamPreservationPolicyRenderCriticalTypesV1.sol";
import {
    StreamPreservationInventoryTypes as T
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import {
    IStreamStaticMetadataRouter as Router
} from "../../interfaces/stream/metadata/IStreamStaticMetadataRouter.sol";
import { IStreamRenderer as Renderer } from "../../interfaces/stream/metadata/IStreamRenderer.sol";
import {
    IStreamStaticMetadataSource as Raw
} from "../../interfaces/stream/metadata/IStreamStaticMetadataSource.sol";
import {
    IStreamScriptBundles as B
} from "../../interfaces/stream/metadata/IStreamScriptBundles.sol";
import {
    StreamCollectionManifestTypes as M
} from "../../interfaces/stream/metadata/StreamCollectionManifestTypes.sol";
import {
    StreamPreservationPolicyRenderCriticalTokenReadsV1 as Tokens
} from "./StreamPreservationPolicyRenderCriticalTokenReadsV1.sol";
import { StreamPreservationInventoryIO as IO } from "./StreamPreservationInventoryIO.sol";
import { StreamPreservationInventoryItems as Items } from "./StreamPreservationInventoryItems.sol";

/// @notice Every ordered script/library chunk from the immutable selected manifest and renderer.
/// @dev URI strings remain declarations in the original manifest. They do not replace the actual
/// executable bytes. Each logical chunk and the complete ordered payload are independently hashed.
library StreamPreservationPolicyRenderCriticalScriptReadsV1 {
    struct Selected {
        uint256 token;
        address renderer;
        bytes32 manifestHash;
        bytes manifest;
        bytes32 bundle;
        B.Facts facts;
    }

    function items(
        S.Dependencies memory d,
        Scoped.Context memory c,
        uint64 ordinal,
        bool libraryOnly
    ) public view returns (T.Item[] memory rows) {
        (uint256 token, Tokens.Original memory original) = Tokens.sourceAt(d, c, ordinal);
        (Router.RawSource memory source,) =
            abi.decode(original.source, (Router.RawSource, Renderer.MetadataConfig));
        if (source.scriptManifest.manifestHash == 0) {
            rows = new T.Item[](1);
            rows[0] = libraryOnly
                ? Items.absent(
                    keccak256("EXECUTABLE_LIBRARY"),
                    d.targets[4],
                    original.selection.configRecordHash,
                    token
                )
                : _row(
                    "INLINE_EXECUTABLE_SCRIPT",
                    d.targets[4],
                    original.selection.configRecordHash,
                    token,
                    bytes(source.script)
                );
            return rows;
        }
        Selected memory s = _selected(d, c, original, source, token);
        if (s.bundle == 0) {
            rows = new T.Item[](libraryOnly ? 1 : 2);
            rows[0] = libraryOnly
                ? Items.absent(keccak256("EXECUTABLE_LIBRARY"), d.targets[1], s.manifestHash, token)
                : _row("ORIGINAL_SCRIPT_MANIFEST", d.targets[1], s.manifestHash, token, s.manifest);
            if (!libraryOnly) {
                rows[1] = _row(
                    "INLINE_EXECUTABLE_SCRIPT",
                    d.targets[4],
                    s.manifestHash,
                    token,
                    bytes(source.script)
                );
            }
            return rows;
        }
        if (libraryOnly) {
            s.bundle = s.facts.libraryBundle;
            if (s.bundle == 0) {
                rows = new T.Item[](1);
                rows[0] = Items.absent(
                    keccak256("EXECUTABLE_LIBRARY"), d.targets[1], s.manifestHash, token
                );
                return rows;
            }
            (s.facts,) = _facts(d, s.bundle);
            if (!s.facts.libraryOnly || s.facts.libraryBundle != 0) {
                revert T.InvalidInventoryItem();
            }
        }
        (B.Facts memory saved, B.RegistrySource memory registry) = _facts(d, s.bundle);
        if (keccak256(abi.encode(saved)) != keccak256(abi.encode(s.facts))) {
            revert T.InventorySourceChanged();
        }
        rows = new T.Item[](uint256(s.facts.chunkCount) + (libraryOnly ? 4 : 3));
        rows[0] = _row("ORIGINAL_SCRIPT_MANIFEST", d.targets[1], s.manifestHash, token, s.manifest);
        rows[1] = _row(
            libraryOnly ? "ORIGINAL_LIBRARY_FACTS" : "ORIGINAL_SCRIPT_FACTS",
            d.targets[1],
            s.bundle,
            token,
            abi.encode(s.facts, registry)
        );
        uint256 first = 2;
        if (libraryOnly) {
            bytes memory declaration = IO.read(
                d.targets[1], abi.encodeCall(B.dependencyManifest, (s.bundle)), 10000, d.sourceGas
            );
            M.DependencyManifest memory dependency = abi.decode(declaration, (M.DependencyManifest));
            IO.canonical(d.targets[1], declaration, abi.encode(dependency));
            if (
                dependency.dependencyHash != s.facts.payloadHash
                    || dependency.sourceType != s.facts.sourceType
                    || dependency.useDependencyRegistry
                        != (s.facts.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY)
            ) {
                revert T.InvalidInventoryItem();
            }
            rows[2] =
                _row("ORIGINAL_DEPENDENCY_MANIFEST", d.targets[1], s.bundle, token, declaration);
            first = 3;
        }
        bytes memory complete = new bytes(s.facts.totalBytes);
        uint256 offset;
        for (uint256 i; i < s.facts.chunkCount; ++i) {
            bytes memory raw = IO.fixedRead(
                d.targets[1], abi.encodeCall(Raw.staticBundleChunk, (s.bundle, i)), 128, d.readGas
            );
            Raw.Chunk memory chunk = abi.decode(raw, (Raw.Chunk));
            IO.canonical(d.targets[1], raw, abi.encode(chunk));
            uint256 maximum = s.facts.sourceType == M.PayloadSourceType.SSTORE2 ? 24576 : 8192;
            if (
                chunk.length == 0 || chunk.length > maximum || chunk.hash == 0
                    || chunk.length > complete.length - offset
            ) {
                revert T.InvalidInventoryItem();
            }
            // The original selected renderer resolves the exact saved registry version/physical split.
            raw = IO.read(
                s.renderer,
                abi.encodeWithSignature("scriptBundleChunk(bytes32,uint256)", s.bundle, i),
                maximum + 64,
                d.sourceGas
            );
            bytes memory part = abi.decode(raw, (bytes));
            IO.canonical(s.renderer, raw, abi.encode(part));
            if (part.length != chunk.length || keccak256(part) != chunk.hash) {
                revert T.InvalidInventoryItem();
            }
            _copy(complete, offset, part);
            offset += part.length;
            rows[first + i] = _row(
                libraryOnly ? "EXECUTABLE_LIBRARY_CHUNK" : "EXECUTABLE_SCRIPT_CHUNK",
                s.renderer,
                s.bundle,
                i,
                part
            );
            rows[first + i].provenanceHash = keccak256(abi.encode(d.targets[1], chunk, registry));
        }
        if (offset != complete.length || keccak256(complete) != s.facts.payloadHash) {
            revert T.InvalidInventoryItem();
        }
        rows[rows.length - 1] = _row(
            libraryOnly ? "COMPLETE_EXECUTABLE_LIBRARY" : "COMPLETE_EXECUTABLE_SCRIPT",
            s.renderer,
            s.bundle,
            token,
            complete
        );
    }

    function _selected(
        S.Dependencies memory d,
        Scoped.Context memory c,
        Tokens.Original memory o,
        Router.RawSource memory source,
        uint256 token
    ) private view returns (Selected memory s) {
        if (
            source.scriptManifest.host != d.targets[1]
                || source.scriptManifest.codeHash != d.codeHashes[1]
        ) revert T.InventorySourceChanged();
        IO.pin(d.targets[1], d.codeHashes[1]);
        s.renderer = o.selection.selection.renderer;
        IO.pin(s.renderer, o.selection.selection.rendererCodeHash);
        s.token = token;
        s.manifestHash = source.scriptManifest.manifestHash;
        s.manifest = IO.read(
            d.targets[1],
            abi.encodeCall(Raw.staticScriptManifest, (s.manifestHash)),
            9504,
            d.sourceGas
        );
        (M.ScriptManifest memory manifest, bytes32 bundle, uint256 cid, address router) =
            abi.decode(s.manifest, (M.ScriptManifest, bytes32, uint256, address));
        IO.canonical(d.targets[1], s.manifest, abi.encode(manifest, bundle, cid, router));
        if (
            cid != c.records.collectionId || router != d.targets[4] || !manifest.executable
                || keccak256(bytes(manifest.mimeType)) != keccak256("application/javascript")
        ) revert T.InvalidInventoryItem();
        s.bundle = bundle;
        bytes32 original;
        if (bundle == 0) {
            bytes32 hash = keccak256(bytes(source.script));
            if (
                manifest.scriptHash != hash || manifest.chunkCount != 1
                    || manifest.sourceType != M.PayloadSourceType.INLINE_CHUNKS
            ) {
                revert T.InvalidInventoryItem();
            }
            original = keccak256(
                abi.encode(
                    keccak256("6529STREAM_CURRENT_SCRIPT_MANIFEST_V1"),
                    d.chainId,
                    d.targets[0],
                    d.targets[1],
                    router,
                    router.codehash,
                    cid,
                    hash,
                    manifest
                )
            );
        } else {
            (s.facts,) = _facts(d, bundle);
            if (
                s.facts.libraryOnly || s.facts.payloadHash != manifest.scriptHash
                    || s.facts.chunkCount != manifest.chunkCount
                    || s.facts.sourceType != manifest.sourceType
            ) revert T.InvalidInventoryItem();
            original = keccak256(
                abi.encode(
                    keccak256("6529STREAM_CHUNKED_SCRIPT_MANIFEST_V1"),
                    d.chainId,
                    d.targets[0],
                    d.targets[1],
                    router,
                    router.codehash,
                    cid,
                    bundle,
                    s.facts,
                    manifest
                )
            );
        }
        if (original != s.manifestHash) revert T.InventorySourceChanged();
    }

    function _facts(S.Dependencies memory d, bytes32 id)
        private
        view
        returns (B.Facts memory f, B.RegistrySource memory registry)
    {
        bytes memory raw =
            IO.fixedRead(d.targets[1], abi.encodeCall(Raw.staticBundle, (id)), 384, d.readGas);
        (f, registry) = abi.decode(raw, (B.Facts, B.RegistrySource));
        IO.canonical(d.targets[1], raw, abi.encode(f, registry));
        if (
            !f.finalized || f.chunkCount == 0 || f.chunkCount > 32 || f.totalBytes == 0
                || f.totalBytes > 786432 || f.payloadHash == 0
                || (f.sourceType != M.PayloadSourceType.INLINE_CHUNKS
                    && f.sourceType != M.PayloadSourceType.SSTORE2
                    && !(f.libraryOnly && f.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY))
        ) revert T.InvalidInventoryItem();
        if (f.sourceType == M.PayloadSourceType.DEPENDENCY_REGISTRY) {
            IO.pin(registry.registry, registry.codeHash);
        }
    }

    function _copy(bytes memory destination, uint256 offset, bytes memory part) private pure {
        uint256 words = part.length & ~uint256(31);
        assembly ("memory-safe") {
            for { let j := 0 } lt(j, words) { j := add(j, 32) } {
                mstore(add(add(destination, 32), add(offset, j)), mload(add(add(part, 32), j)))
            }
        }
        for (uint256 i = words; i < part.length; ++i) {
            destination[offset + i] = part[i];
        }
    }

    function _row(
        string memory role,
        address host,
        bytes32 record,
        uint256 index,
        bytes memory value
    ) private pure returns (T.Item memory) {
        return Items.bytesItem(
            T.Kind.NATIVE_BYTES, keccak256(bytes(role)), host, record, index, value
        );
    }
}

