/// @notice Exact preservation output and original source rows for each authoritative scope ordinal.
/// @dev This finite output segment is not a complete script/dependency/definition inventory.
/// The host must require the full current source context before appending and before sealing.
/// This profile shares the scoped reference bounds: JSON 65,536, HTML 40,960 and image
/// 2,048 bytes. Larger Renderer outputs need a separately measured segmented profile.
library StreamPreservationPolicyRenderCriticalTokenReadsV1 {
    struct Original {
        Selection.TokenSelection selection;
        Content.Output output;
        bytes identity;
        bytes entropy;
        bytes config;
        bytes source;
    }

    /// @dev Authenticated source coordinate shared by the finite per-token inventory workers.
    function sourceAt(S.Dependencies memory d, Scoped.Context memory c, uint64 index)
        public
        view
        returns (uint256 token, Original memory original)
    {
        (Snapshot.Dependencies memory sd,) = Sources.bindings(d);
        if (index >= c.records.tokenCount) revert T.InvalidInventoryItem();
        token = uint256(
            IO.word(
                sd.targets[5],
                abi.encodeCall(Membership.scopeTokenAt, (c.source.scope, index)),
                d.readGas
            )
        );
        if (token == 0) revert T.InvalidInventoryItem();
        original = _original(d, c, sd, index, token);
    }

    function tokenItems(
        S.Dependencies memory d,
        Scoped.Context memory c,
        uint64 index,
        Content.Payload memory supplied
    ) public view returns (T.Item[] memory rows) {
        (Snapshot.Dependencies memory sd,) = Sources.bindings(d);
        if (
            index >= c.records.tokenCount || supplied.tokenId == 0
                || supplied.tokenId
                    != uint256(
                        IO.word(
                            sd.targets[5],
                            abi.encodeCall(Membership.scopeTokenAt, (c.source.scope, index)),
                            d.readGas
                        )
                    )
        ) revert T.InvalidInventoryItem();
        Original memory o = _original(d, c, sd, index, supplied.tokenId);
        bytes memory data = _bytes(
            d.targets[0],
            abi.encodeCall(IStreamCoreMint.tokenData, (supplied.tokenId)),
            16384,
            d.sourceGas
        );
        // Observe the saved independently admitted producer, not the live display projection.
        if (supplied.producer != o.output.preservation.producer) revert T.InvalidInventoryItem();
        bytes memory json = _bytes(
            o.output.preservation.producer,
            abi.encodeWithSignature("preservationTokenJSON(uint256)", supplied.tokenId),
            65536,
            d.sourceGas
        );
        bytes memory html = _bytes(
            o.output.preservation.producer,
            abi.encodeWithSignature("preservationTokenHTML(uint256)", supplied.tokenId),
            40960,
            d.sourceGas
        );
        if (
            keccak256(data) != o.output.leaf.tokenDataHash || json.length == 0
                || keccak256(json) != o.output.leaf.metadataHash || html.length == 0
                || keccak256(html) != o.output.leaf.animationHash
                || o.output.htmlHash != keccak256(html)
                || keccak256(supplied.animation) != keccak256(html) || supplied.image.length > 2048
                || o.output.leaf.contentHash != 0
                || (supplied.image.length == 0
                        ? o.output.leaf.imageHash != 0
                        : keccak256(supplied.image) != o.output.leaf.imageHash)
        ) {
            revert T.InvalidInventoryItem();
        }
        if (o.output.entropy.terminal
                ? !StreamPolicyContentBytesV2.matches(json, html, data)
                : !StreamOnchainContentBytes.matchesAnimation(json, html)) revert T.InvalidInventoryItem();
        rows = new T.Item[](10);
        bytes32 record = c.records.checkpointHash;
        uint256 token = supplied.tokenId;
        rows[0] = Items.bytesItem(
            T.Kind.NATIVE_BYTES, keccak256("TOKEN_DATA"), d.targets[0], record, token, data
        );
        rows[1] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("PRESERVATION_TOKEN_METADATA_JSON"),
            o.output.preservation.producer,
            record,
            token,
            json
        );
        rows[2] = supplied.image.length == 0
            ? Items.absent(
                keccak256("PRESERVATION_TOKEN_IMAGE"), o.output.preservation.producer, record, token
            )
            : Items.bytesItem(
                T.Kind.NATIVE_BYTES,
                keccak256("PRESERVATION_TOKEN_IMAGE"),
                o.output.preservation.producer,
                record,
                token,
                supplied.image
            );
        rows[3] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("PRESERVATION_TOKEN_ANIMATION_HTML"),
            o.output.preservation.producer,
            record,
            token,
            html
        );
        rows[4] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("ORIGINAL_TOKEN_IDENTITY_LIFECYCLE"),
            d.targets[0],
            record,
            token,
            o.identity
        );
        rows[5] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("ORIGINAL_TOKEN_ENTROPY"),
            o.selection.sources[3],
            record,
            token,
            o.entropy
        );
        rows[6] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("STATIC_SELECTION_ROW"),
            sd.targets[6],
            c.source.content.selectionId,
            index,
            abi.encode(o.selection)
        );
        rows[7] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("STATIC_OUTPUT_ROW"),
            sd.targets[7],
            record,
            index,
            abi.encode(o.output)
        );
        rows[8] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("ORIGINAL_STATIC_CONFIG"),
            d.targets[4],
            o.selection.configRecordHash,
            token,
            o.config
        );
        rows[9] = Items.bytesItem(
            T.Kind.NATIVE_BYTES,
            keccak256("ORIGINAL_STATIC_RAW_SOURCE"),
            d.targets[4],
            o.selection.configRecordHash,
            token,
            o.source
        );
    }

    function _original(
        S.Dependencies memory d,
        Scoped.Context memory c,
        Snapshot.Dependencies memory sd,
        uint64 index,
        uint256 token
    ) private view returns (Original memory o) {
        bytes memory raw = IO.fixedRead(
            sd.targets[6],
            abi.encodeCall(Selection.selectionAt, (c.source.content.selectionId, index)),
            896,
            d.readGas
        );
        o.selection = abi.decode(raw, (Selection.TokenSelection));
        IO.canonical(sd.targets[6], raw, abi.encode(o.selection));
        raw = IO.fixedRead(
            sd.targets[7],
            abi.encodeCall(Content.outputAt, (c.records.checkpointHash, index)),
            1152,
            d.readGas
        );
        o.output = abi.decode(raw, (Content.Output));
        IO.canonical(sd.targets[7], raw, abi.encode(o.output));
        bytes32 family = FamilyRead.requirePlan(
            d,
            sd.targets[7],
            sd.codeHashes[7],
            c.records.checkpointHash,
            c.source.content,
            c.source.outputs,
            false
        );
        _preservation(d, o, family);
        if (
            o.selection.tokenId != token || o.output.leaf.tokenId != token
                || o.output.selectionRowHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_STATIC_SELECTION_ROW_V1"),
                            d.chainId,
                            d.targets[0],
                            d.targets[4],
                            o.selection
                        )
                    )
        ) revert T.InvalidInventoryItem();
        raw = IO.fixedRead(
            d.targets[0], abi.encodeCall(Core.tokenCollectionIdentity, (token)), 128, d.readGas
        );
        (bool exists, uint256 cid, uint256 serial, bool burned) =
            abi.decode(raw, (bool, uint256, uint256, bool));
        IO.canonical(d.targets[0], raw, abi.encode(exists, cid, serial, burned));
        uint256 lifecycle =
            uint256(IO.word(d.targets[0], abi.encodeCall(Core.tokenLifecycle, (token)), d.readGas));
        if (
            !exists || cid != c.source.scope.collectionId || serial == 0
                || lifecycle != (burned ? 3 : 2)
        ) {
            revert T.InvalidInventoryItem();
        }
        // The permanent serial comes from Core; an ordinal is never converted to serial+1.
        o.identity = abi.encode(token, cid, serial, burned, uint8(lifecycle), index);
        address coordinator = IO.addressWord(
            d.targets[0], abi.encodeCall(Core.coordinatorAtMint, (token)), d.readGas
        );
        if (coordinator != o.selection.sources[3]) revert T.InventorySourceChanged();
        IO.pin(coordinator, o.selection.sourceCodeHashes[3]);
        o.entropy = IO.fixedRead(
            sd.targets[10], abi.encodeCall(Policy.tokenEntropyReadiness, (token)), 320, d.sourceGas
        );
        Policy.TokenReadiness memory facts = abi.decode(o.entropy, (Policy.TokenReadiness));
        IO.canonical(sd.targets[10], o.entropy, abi.encode(facts));
        if (
            keccak256(o.entropy) != keccak256(abi.encode(o.output.entropy))
                || facts.coordinator != coordinator
                || facts.coordinatorCodeHash != o.selection.sourceCodeHashes[3]
                || facts.policyHash == 0
        ) revert T.InvalidInventoryItem();
        address readiness =
            IO.addressWord(sd.targets[7], abi.encodeCall(Content.terminalReadiness, ()), d.readGas);
        if (readiness.code.length == 0) revert T.InvalidInventoryItem();
        if (facts.terminal) {
            if (
                facts.finalized || facts.seed != 0 || facts.renderRequirement != 1
                    || !((facts.status == 1 && facts.mode == 0)
                        || (facts.status == 2 && facts.mode == 2))
            ) revert T.InvalidInventoryItem();
            bytes memory admitted = IO.fixedRead(
                readiness,
                abi.encodeCall(Terminal.requireTerminalRenderReady, (token)),
                608,
                d.sourceGas
            );
            Terminal.Evidence memory a = abi.decode(admitted, (Terminal.Evidence));
            IO.canonical(readiness, admitted, abi.encode(a));
            if (
                keccak256(admitted) != o.output.terminalAdmissionHash
                    || keccak256(abi.encode(a.entropy)) != keccak256(o.entropy)
                    || a.configRecordHash != o.selection.configRecordHash
                    || a.versionKey != o.selection.selection.versionKey
                    || a.renderer != o.selection.selection.renderer
                    || a.rendererCodeHash != o.selection.selection.rendererCodeHash
                    || a.registry != o.selection.selection.registry
                    || a.registryCodeHash != o.selection.selection.registryCodeHash
                    || a.policyChainHash != c.source.content.policyChainHash || a.admissionHash == 0
                    || a.evidenceHash == 0
            ) revert T.InvalidInventoryItem();
        } else {
            if (
                !facts.finalized || facts.status != 5 || facts.mode != 2
                    || facts.renderRequirement != 0 || o.output.terminalAdmissionHash != 0
            ) revert T.InvalidInventoryItem();
            bytes memory nativeFacts = IO.fixedRead(
                coordinator,
                abi.encodeCall(Entropy.staticTokenRenderFacts, (token)),
                96,
                d.sourceGas
            );
            (uint8 status, bytes32 seed, address provider) =
                abi.decode(nativeFacts, (uint8, bytes32, address));
            IO.canonical(coordinator, nativeFacts, abi.encode(status, seed, provider));
            if (status != 5 || seed != facts.seed) revert T.InvalidInventoryItem();
        }
        if (
            o.output.sourceFactsHash
                != keccak256(
                    abi.encode(
                        keccak256("6529STREAM_PRESERVATION_POLICY_CONTENT_V1"),
                        c.source.content.preservationProfile,
                        o.output.preservation,
                        o.output.preservationAdmission,
                        o.selection.configHash,
                        o.selection.rawSourceHash,
                        coordinator,
                        o.entropy,
                        sd.targets[10],
                        sd.codeHashes[10],
                        c.source.content.inventoryHash,
                        c.source.content.policyChainHash,
                        readiness,
                        readiness.codehash,
                        o.output.terminalAdmissionHash
                    )
                )
        ) revert T.InvalidInventoryItem();
        o.config = IO.read(
            d.targets[4],
            abi.encodeCall(Router.metadataConfigRecord, (o.selection.configRecordHash)),
            8192,
            d.sourceGas
        );
        Router.ConfigRecord memory config = abi.decode(o.config, (Router.ConfigRecord));
        IO.canonical(d.targets[4], o.config, abi.encode(config));
        if (
            keccak256(o.config) != o.selection.configHash
                || config.recordHash != o.selection.configRecordHash || config.collectionId != cid
                || (config.tokenId != 0 && config.tokenId != token) || !config.config.frozen
                || config.sourceSnapshotHash != o.selection.sourceSnapshotHash
                || keccak256(abi.encode(config.selection))
                    != keccak256(abi.encode(o.selection.selection))
        ) revert T.InvalidInventoryItem();
        config.recordHash = 0;
        if (
            keccak256(
                    abi.encode(
                        keccak256("6529STREAM_STATIC_METADATA_CONFIG_RECORD_V1"),
                        d.targets[0],
                        d.targets[4],
                        config
                    )
                ) != o.selection.configRecordHash
        ) revert T.InvalidInventoryItem();
        o.source = IO.read(
            d.targets[4],
            abi.encodeCall(Router.staticRenderSourceForConfig, (cid, o.selection.configRecordHash)),
            24000,
            d.sourceGas
        );
        (Router.RawSource memory source, Renderer.MetadataConfig memory cfg) =
            abi.decode(o.source, (Router.RawSource, Renderer.MetadataConfig));
        IO.canonical(d.targets[4], o.source, abi.encode(source, cfg));
        if (
            !source.configured || source.chainId != d.chainId
                || keccak256(abi.encode(cfg)) != keccak256(abi.encode(config.config))
                || keccak256(abi.encode(source)) != o.selection.rawSourceHash
                || keccak256(abi.encode(keccak256("6529STREAM_STATIC_SOURCE_SNAPSHOT_V1"), source))
                    != o.selection.sourceSnapshotHash
        ) {
            revert T.InvalidInventoryItem();
        }
    }

    function _preservation(S.Dependencies memory d, Original memory o, bytes32 family)
        private
        view
    {
        if (
            !FamilyRead.allows(family, o.output.preservation.profile)
                || o.output.preservation.core != d.targets[0]
                || o.output.preservation.metadataRouter != d.targets[4]
                || o.output.preservationAdmission.registry != o.selection.selection.registry
                || o.output.preservationAdmission.registryCodeHash
                    != o.selection.selection.registryCodeHash
                || o.output.preservationAdmission.versionKey != o.selection.selection.versionKey
                || o.output.preservationAdmission.registrationHash == 0
                || o.output.preservationAdmission.readSetHash == 0
                || o.output.preservationAdmission.analysisHash == 0
                || o.output.preservationAdmission.goldenHash == 0
        ) revert T.InventorySourceChanged();
        IO.pin(o.selection.selection.registry, o.selection.selection.registryCodeHash);
        Binding.requireCurrent(o.output.preservation, o.selection, d.readGas);
        bytes memory raw = IO.fixedRead(
            o.selection.selection.registry,
            abi.encodeCall(
                Registry.requirePreservation,
                (
                    o.selection.selection.versionKey,
                    o.output.preservation.producer,
                    o.output.preservation.profile
                )
            ),
            512,
            d.sourceGas
        );
        IO.canonical(
            o.selection.selection.registry,
            raw,
            abi.encode(o.output.preservation, o.output.preservationAdmission)
        );
    }

    function _bytes(address target, bytes memory input, uint256 maximum, uint256 cap)
        private
        view
        returns (bytes memory value)
    {
        bytes memory raw = IO.read(target, input, maximum + 64, cap);
        value = abi.decode(raw, (bytes));
        IO.canonical(target, raw, abi.encode(value));
        if (value.length > maximum) revert T.InventoryRead(target);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamPreservationTokenProducerProfilesV1 as Family
} from "../../interfaces/stream/finality/StreamPreservationTokenProducerProfilesV1.sol";
import {
    StreamPreservationPolicyRenderCriticalStateV1 as State
} from "./StreamPreservationPolicyRenderCriticalStateV1.sol";
import {
    StreamPreservationInventoryTypes as T
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import {
    StreamPreservationPolicyRenderCriticalTokenReadsV1 as Tokens
} from "./StreamPreservationPolicyRenderCriticalTokenReadsV1.sol";
import {
    StreamPreservationPolicyRenderCriticalScriptReadsV1 as Scripts
} from "./StreamPreservationPolicyRenderCriticalScriptReadsV1.sol";
import {
    StreamPreservationPolicyRenderCriticalRendererReadsV1 as Renderers
} from "./StreamPreservationPolicyRenderCriticalRendererReadsV1.sol";
import {
    StreamPreservationPolicyRenderCriticalProfileReadsV1 as Profiles
} from "./StreamPreservationPolicyRenderCriticalProfileReadsV1.sol";
import {
    IStreamPreservationPolicyContentCheckpointV1 as Content
} from "../../interfaces/stream/finality/IStreamPreservationPolicyContentCheckpointV1.sol";

import {
    StreamPreservationPolicyAdmissionInventoryV1 as Preservation
} from "./StreamPreservationPolicyAdmissionInventoryV1.sol";

library StreamPreservationPolicyRenderCriticalTokenStagesV1 {
    function appendOutput(State.State storage s, bytes32 id, Content.Payload memory payload)
        public
    {
        _stage(s, id, 0);
        uint64 ordinal = s.records.plans[id].nextToken;
        State.append(
            s,
            id,
            Tokens.tokenItems(s.records.dependencies, s.contexts[id], ordinal, payload),
            _witness(s, id, ordinal, 0, 0, 0)
        );
        s.progress[id].phase = 1;
    }

    function appendScript(State.State storage s, bytes32 id, bool libraryOnly) public {
        uint8 phase = libraryOnly ? 2 : 1;
        _stage(s, id, phase);
        uint64 ordinal = s.records.plans[id].nextToken;
        T.Item[] memory rows =
            Scripts.items(s.records.dependencies, s.contexts[id], ordinal, libraryOnly);
        State.append(s, id, rows, _witness(s, id, ordinal, phase, 0, 0));
        s.progress[id].phase = phase + 1;
    }

    function appendRenderer(State.State storage s, bytes32 id) public {
        _stage(s, id, 3);
        (T.Item memory row, uint64 count) = Renderers.item(
            s.records.dependencies,
            s.contexts[id],
            s.records.plans[id].nextToken,
            s.progress[id].row
        );
        _row(s, id, row, count);
    }

    function appendProfile(State.State storage s, bytes32 id) public {
        _stage(s, id, 4);
        (T.Item memory row, uint64 count) = Profiles.item(
            s.records.dependencies,
            s.contexts[id],
            s.records.plans[id].nextToken,
            s.progress[id].row
        );
        _row(s, id, row, count);
    }

    function appendPreservation(State.State storage s, bytes32 id) public {
        appendPreservation(s, id, false);
    }

    function appendPreservation(State.State storage s, bytes32 id, bool familyV2) public {
        _stage(s, id, 5);
        (, Tokens.Original memory o) =
            Tokens.sourceAt(s.records.dependencies, s.contexts[id], s.records.plans[id].nextToken);
        T.Item memory row;
        uint64 count;
        if (familyV2) {
            (row, count) = Preservation.itemForPlan(
                s.records.dependencies,
                s.contexts[id].source.content,
                o.selection,
                o.output,
                s.progress[id].row
            );
        } else {
            (row, count) = Preservation.item(
                s.records.dependencies, o.selection, o.output, s.progress[id].row
            );
        }
        _row(s, id, row, count);
    }

    function _row(State.State storage s, bytes32 id, T.Item memory row, uint64 count) private {
        State.Progress storage progress = s.progress[id];
        if (count == 0 || progress.row >= count || (progress.row != 0 && progress.count != count)) {
            revert T.InventorySourceChanged();
        }
        progress.count = count;
        T.Item[] memory rows = new T.Item[](1);
        rows[0] = row;
        State.append(
            s,
            id,
            rows,
            _witness(s, id, s.records.plans[id].nextToken, progress.phase, progress.row, count)
        );
        if (++progress.row == count) {
            progress.row = 0;
            progress.count = 0;
            if (progress.phase == 5) {
                progress.phase = 0;
                ++s.records.plans[id].nextToken;
            } else {
                ++progress.phase;
            }
        }
    }

    function _stage(State.State storage s, bytes32 id, uint8 phase) private view {
        State.stage(s, id, 8);
        if (
            s.progress[id].phase != phase
                || s.records.plans[id].nextToken >= s.records.plans[id].tokenCount
        ) revert T.InventoryIncomplete();
    }

    function _witness(
        State.State storage s,
        bytes32 id,
        uint64 ordinal,
        uint8 phase,
        uint64 row,
        uint64 count
    ) private view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_PRESERVATION_POLICY_TOKEN_STAGE_V1"),
                s.contexts[id].records.checkpointHash,
                s.contexts[id].source.content.selectionHash,
                ordinal,
                phase,
                row,
                count
            )
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {
    StreamPreservationInventoryTypes as T
} from "../../interfaces/stream/preservation/StreamPreservationInventoryTypes.sol";
import {
    StreamWorkRecordTypes as W
} from "../../interfaces/stream/metadata/StreamWorkRecordTypes.sol";
import {
    StreamRightsRecordTypes as R
} from "../../interfaces/stream/metadata/StreamRightsRecordTypes.sol";
import {
    StreamConservationRecordTypes as C
} from "../../interfaces/stream/metadata/StreamConservationRecordTypes.sol";
import "../records/StreamWorkRecordJson.sol";
import "../records/StreamRightsRecordJson.sol";
import "../records/StreamArtistIntentJson.sol";
import "../records/StreamArtistIntentWaiverJson.sol";
import "../records/StreamArtistInterviewJson.sol";
import "../records/StreamConservationFormatJson.sol";

/// @notice Complete ordered reference walks of the exact supported typed original payloads.
/// @dev The fixed producer supplies the authenticated payload hash and source record. This pure
/// library cannot authenticate either. All six hash algorithms survive unchanged; coverage must
/// separately establish correspondence, and must reject unsupported nonempty references.
library StreamPreservationTypedReferences {
    bytes32 private constant RAW = keccak256("RAW_BYTES");
    bytes32 private constant JCS = keccak256("RFC8785_JCS");

    function work(address source, bytes32 record, bytes32 payloadHash, W.Description memory value)
        public
        pure
        returns (T.Item[] memory items)
    {
        _payload(StreamWorkRecordJson.serialize(value), payloadHash);
        if (value.form != W.Form.FULL || value.full.format.kind != W.FormatKind.CATALOG) {
            return new T.Item[](0);
        }
        W.Catalog memory catalog = value.full.format.catalog;
        uint256 count = 1;
        for (uint256 i; i < catalog.entries.length; ++i) {
            if (catalog.entries[i].kind == W.MappingKind.SPECIFICATION) ++count;
        }
        items = new T.Item[](count);
        bytes memory document = StreamWorkFormatJson.catalogDocument(catalog);
        items[0] = _catalog(source, record, 0, catalog.name, document);
        uint256 next = 1;
        for (uint256 i; i < catalog.entries.length; ++i) {
            W.CatalogEntry memory entry = catalog.entries[i];
            if (entry.kind == W.MappingKind.SPECIFICATION) {
                items[next++] = _reference(
                    source,
                    record,
                    i,
                    keccak256("WORK_FORMAT_SPECIFICATION"),
                    C.Reference(
                        1,
                        RAW,
                        abi.encodePacked(entry.specification.digest),
                        entry.specification.uri
                    )
                );
            }
        }
    }

    function rights(address source, bytes32 record, bytes32 payloadHash, R.Statement memory value)
        public
        pure
        returns (T.Item[] memory items)
    {
        _payload(StreamRightsRecordJson.serialize(value), payloadHash);
        R.Grant[6] memory grants = [
            value.grants.aiTraining,
            value.grants.derivative,
            value.grants.exhibition,
            value.grants.print,
            value.grants.publication,
            value.grants.reproduction
        ];
        uint256 count = value.instrument.exists ? 1 : 0;
        for (uint256 i; i < 6; ++i) {
            if (grants[i].conditions.kind == R.ConditionKind.DOCUMENT) ++count;
        }
        items = new T.Item[](count);
        uint256 next;
        if (value.instrument.exists) {
            items[next++] = _rightsDocument(
                source, record, 0, keccak256("RIGHTS_INSTRUMENT"), value.instrument
            );
        }
        for (uint256 i; i < 6; ++i) {
            if (grants[i].conditions.kind == R.ConditionKind.DOCUMENT) {
                items[next++] = _rightsDocument(
                    source,
                    record,
                    i,
                    keccak256("RIGHTS_USE_CONDITION"),
                    grants[i].conditions.document
                );
            }
        }
    }

    function intent(address source, bytes32 record, bytes32 payloadHash, C.Intent memory value)
        public
        pure
        returns (T.Item[] memory items)
    {
        _payload(StreamArtistIntentJson.serialize(value), payloadHash);
        items = new T.Item[](10);
        C.Reference[9] memory refs = [
            value.display.scale,
            value.display.timing,
            value.display.color,
            value.display.interaction,
            value.display.motion,
            value.display.frameRate,
            value.variabilityTolerances,
            value.dependencyAging,
            value.significantProperties
        ];
        bytes32[9] memory roles = [
            keccak256("DISPLAY_SCALE"),
            keccak256("DISPLAY_TIMING"),
            keccak256("DISPLAY_COLOR"),
            keccak256("DISPLAY_INTERACTION"),
            keccak256("DISPLAY_MOTION"),
            keccak256("DISPLAY_FRAME_RATE"),
            keccak256("VARIABILITY_TOLERANCES"),
            keccak256("DEPENDENCY_AGING"),
            keccak256("SIGNIFICANT_PROPERTIES")
        ];
        for (uint256 i; i < refs.length; ++i) {
            items[i] = _reference(source, record, i, roles[i], refs[i]);
        }
        items[9] = _interviewEntry(source, record, value.interview);
    }

    function waiver(
        address source,
        bytes32 record,
        bytes32 payloadHash,
        C.IntentWaiver memory value
    ) public pure returns (T.Item[] memory items) {
        _payload(StreamArtistIntentWaiverJson.serialize(value), payloadHash);
        items = new T.Item[](2);
        items[0] =
            _reference(source, record, 0, keccak256("ARTIST_INTENT_WAIVER"), value.waiverStatement);
        items[1] = _interviewEntry(source, record, value.interview);
    }

    function interview(
        address source,
        bytes32 record,
        bytes32 payloadHash,
        C.Interview memory value
    ) public pure returns (T.Item[] memory items) {
        _payload(StreamArtistInterviewJson.serialize(value), payloadHash);
        uint256 count = 2 + value.participants.length + value.captures.length
            + _formatCount(value.transcript.format);
        for (uint256 i; i < value.captures.length; ++i) {
            count += _formatCount(value.captures[i].payload.format);
        }
        items = new T.Item[](count);
        uint256 next;
        items[next++] = _reference(
            source, record, 0, keccak256("INTERVIEW_INSTRUMENT"), value.instrument.document
        );
        for (uint256 i; i < value.participants.length; ++i) {
            T.Item memory row = _reference(
                source,
                record,
                i,
                keccak256("INTERVIEW_PARTICIPANT"),
                value.participants[i].identity
            );
            row.provenanceHash =
                keccak256(abi.encode(value.participants[i].role, value.participants[i].otherRole));
            items[next++] = row;
        }
        items[next++] =
            _formatted(source, record, 0, keccak256("INTERVIEW_TRANSCRIPT"), value.transcript);
        next = _format(items, next, source, record, 0, value.transcript.format);
        for (uint256 i; i < value.captures.length; ++i) {
            C.Capture memory capture = value.captures[i];
            T.Item memory row =
                _formatted(source, record, i, keccak256("INTERVIEW_CAPTURE"), capture.payload);
            row.provenanceHash = keccak256(abi.encode(capture.kind));
            items[next++] = row;
            next = _format(items, next, source, record, i + 1, capture.payload.format);
        }
        if (next != count) revert T.InvalidInventoryItem();
    }

    function _formatCount(C.Format memory format) private pure returns (uint256 count) {
        if (format.kind != C.FormatKind.CATALOG) return 0;
        count = 1;
        for (uint256 i; i < format.catalog.entries.length; ++i) {
            if (format.catalog.entries[i].kind == C.MappingKind.SPECIFICATION) ++count;
        }
    }

    function _format(
        T.Item[] memory items,
        uint256 next,
        address source,
        bytes32 record,
        uint256 formatIndex,
        C.Format memory format
    ) private pure returns (uint256) {
        if (format.kind != C.FormatKind.CATALOG) return next;
        bytes memory document = StreamConservationFormatJson.catalogDocument(format.catalog);
        items[next++] = _catalog(source, record, formatIndex, format.catalog.name, document);
        for (uint256 i; i < format.catalog.entries.length; ++i) {
            C.CatalogEntry memory entry = format.catalog.entries[i];
            if (entry.kind == C.MappingKind.SPECIFICATION) {
                T.Item memory row = _reference(
                    source,
                    record,
                    i,
                    keccak256("INTERVIEW_FORMAT_SPECIFICATION"),
                    entry.specification
                );
                row.provenanceHash = keccak256(abi.encode(formatIndex, entry.entryId));
                items[next++] = row;
            }
        }
        return next;
    }

    function _formatted(
        address source,
        bytes32 record,
        uint256 index,
        bytes32 role,
        C.Payload memory payload
    ) private pure returns (T.Item memory row) {
        row = _reference(source, record, index, role, payload.content);
        row.formatId = payload.format.formatId;
        if (payload.format.kind == C.FormatKind.CATALOG) {
            row.catalogId = keccak256(bytes(payload.format.catalog.name));
            row.catalogHash =
                keccak256(StreamConservationFormatJson.catalogDocument(payload.format.catalog));
        }
    }

    function _interviewEntry(address source, bytes32 record, C.InterviewEntry memory entry)
        private
        pure
        returns (T.Item memory row)
    {
        bool present = entry.status == C.InterviewStatus.PRESENT;
        row = _reference(
            source,
            record,
            0,
            present ? keccak256("PRESENT_INTERVIEW_PAYLOAD") : keccak256("INTERVIEW_WAIVER"),
            present ? entry.record.payload : entry.waiverStatement
        );
        if (present) {
            row.schemaId = entry.record.schemaId;
            // The original parent commits a concrete record locator as well as a payload ref.
            row.provenanceHash = keccak256(
                abi.encode(
                    entry.record.chainId,
                    entry.record.core,
                    entry.record.host,
                    entry.record.recordHash,
                    entry.record.profileHash
                )
            );
        }
    }

    function _rightsDocument(
        address source,
        bytes32 record,
        uint256 index,
        bytes32 role,
        R.Document memory doc
    ) private pure returns (T.Item memory) {
        return _reference(
            source, record, index, role, C.Reference(1, RAW, abi.encodePacked(doc.digest), doc.uri)
        );
    }

    function _catalog(
        address source,
        bytes32 record,
        uint256 index,
        string memory name,
        bytes memory document
    ) private pure returns (T.Item memory row) {
        row = _reference(
            source,
            record,
            index,
            keccak256("REGISTERED_FORMAT_CATALOG"),
            C.Reference(1, JCS, abi.encodePacked(keccak256(document)), "")
        );
        row.kind = T.Kind.REGISTERED_DOCUMENT;
        row.byteSize = uint64(document.length);
        row.catalogId = keccak256(bytes(name));
        row.catalogHash = keccak256(document);
    }

    function _reference(
        address source,
        bytes32 record,
        uint256 index,
        bytes32 role,
        C.Reference memory ref
    ) private pure returns (T.Item memory row) {
        row.kind = T.Kind.EXTERNAL_REFERENCE;
        row.source = source;
        row.sourceRecord = record;
        row.sourceIndex = index;
        row.role = role;
        row.algorithm = ref.algorithm;
        row.canonicalizationId = ref.canonicalizationId;
        row.digest = ref.digest;
        row.uri = ref.uri;
    }

    function _payload(bytes memory exact, bytes32 expected) private pure {
        if (expected == 0 || keccak256(exact) != expected) revert T.InvalidInventoryItem();
    }
}

