// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamConservationRecordFields.sol";

/// @notice Exact format declarations and complete supported catalog reconstruction.
/// @dev Actual consumers authenticate registered schema/profile/content. No format detection.
library StreamConservationFormatJson {
    error InvalidConservationFormat();

    function serialize(StreamConservationRecordTypes.Format memory f)
        public
        pure
        returns (string memory)
    {
        if (f.kind == StreamConservationRecordTypes.FormatKind.PRONOM) {
            if (
                bytes(f.catalog.name).length != 0 || f.catalog.entries.length != 0
                    || f.catalog.selectedEntryId != 0
            ) revert InvalidConservationFormat();
            _puid(f.puid);
            if (f.formatId != keccak256(bytes(string.concat("PRONOM:", f.puid)))) {
                revert InvalidConservationFormat();
            }
            return string.concat(
                '{"formatId":',
                StreamRecordJson.hexValue(f.formatId),
                ',"kind":"pronom","puid":',
                StreamRecordJson.quote(f.puid, 32, false),
                "}"
            );
        }
        if (bytes(f.puid).length != 0 || f.formatId != f.catalog.selectedEntryId) {
            revert InvalidConservationFormat();
        }
        bytes memory document = catalogDocument(f.catalog);
        string memory selected;
        for (uint256 i; i < f.catalog.entries.length; ++i) {
            if (f.catalog.entries[i].entryId == f.formatId) {
                selected = _mapping(f.catalog.entries[i]);
            }
        }
        return string.concat(
            '{"catalog":{"documentHash":',
            StreamRecordJson.hexValue(keccak256(document)),
            ',"documentId":',
            StreamRecordJson.hexValue(keccak256(bytes(f.catalog.name))),
            ',"name":',
            StreamRecordJson.quote(f.catalog.name, 128, false),
            '},"formatId":',
            StreamRecordJson.hexValue(f.formatId),
            ',"kind":"catalog","mapping":',
            selected,
            "}"
        );
    }

    /// @notice All entries are checked, ordered and committed, including unselected entries.
    function catalogDocument(StreamConservationRecordTypes.Catalog memory c)
        public
        pure
        returns (bytes memory)
    {
        bytes memory name = bytes(c.name);
        if (
            name.length == 0 || name.length > 128 || c.entries.length == 0 || c.selectedEntryId == 0
        ) {
            revert InvalidConservationFormat();
        }
        for (uint256 i; i < name.length; ++i) {
            bytes1 b = name[i];
            if (!((b >= "A" && b <= "Z") || (b >= "a" && b <= "z") || (b >= "0" && b <= "9")
                        || b == "_" || b == "." || b == "-")) revert InvalidConservationFormat();
        }
        bytes[] memory rows = new bytes[](c.entries.length);
        bytes32[] memory ids = new bytes32[](c.entries.length);
        bool found;
        for (uint256 i; i < c.entries.length; ++i) {
            bytes32 id = c.entries[i].entryId;
            if (id == 0) revert InvalidConservationFormat();
            ids[i] = id;
            if (id == c.selectedEntryId) found = true;
            rows[i] = bytes(
                string.concat(
                    '{"entryId":',
                    StreamRecordJson.hexValue(id),
                    ',"mapping":',
                    _mapping(c.entries[i]),
                    "}"
                )
            );
        }
        if (!found) revert InvalidConservationFormat();
        _unique(ids);
        return StreamConservationRecordFields.requirePayloadSize(
            bytes(
                string.concat(
                    '{"entries":', StreamConservationRecordFields.arrayJSON(rows), ',"version":1}'
                )
            )
        );
    }

    function _mapping(StreamConservationRecordTypes.CatalogEntry memory e)
        private
        pure
        returns (string memory)
    {
        if (e.kind == StreamConservationRecordTypes.MappingKind.PRONOM) {
            StreamConservationRecordFields.requireEmptyReference(e.specification);
            _puid(e.puid);
            return string.concat(
                '{"kind":"pronom","puid":', StreamRecordJson.quote(e.puid, 32, false), "}"
            );
        }
        if (bytes(e.puid).length != 0) revert InvalidConservationFormat();
        return string.concat(
            '{"kind":"specification","specification":',
            StreamConservationRecordFields.referenceJSON(e.specification),
            "}"
        );
    }

    function _puid(string memory value) private pure {
        bytes memory b = bytes(value);
        uint256 first;
        if (b.length >= 5 && b[0] == "f" && b[1] == "m" && b[2] == "t" && b[3] == "/") {
            first = 4;
        } else if (
            b.length >= 7 && b[0] == "x" && b[1] == "-" && b[2] == "f" && b[3] == "m" && b[4] == "t"
                && b[5] == "/"
        ) {
            first = 6;
        } else {
            revert InvalidConservationFormat();
        }
        if (b.length > 32 || b[first] < "1" || b[first] > "9") revert InvalidConservationFormat();
        for (uint256 i = first + 1; i < b.length; ++i) {
            if (b[i] < "0" || b[i] > "9") revert InvalidConservationFormat();
        }
    }

    function _unique(bytes32[] memory a) private pure {
        for (uint256 i = a.length / 2; i != 0;) {
            --i;
            _sift(a, i, a.length);
        }
        for (uint256 end = a.length; end > 1;) {
            --end;
            (a[0], a[end]) = (a[end], a[0]);
            _sift(a, 0, end);
        }
        for (uint256 i = 1; i < a.length; ++i) {
            if (a[i] == a[i - 1]) revert InvalidConservationFormat();
        }
    }

    function _sift(bytes32[] memory a, uint256 root, uint256 n) private pure {
        while (root < n / 2) {
            uint256 child = root * 2 + 1;
            if (child + 1 < n && a[child] < a[child + 1]) ++child;
            if (a[root] >= a[child]) return;
            (a[root], a[child]) = (a[child], a[root]);
            root = child;
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @notice RFC5646 syntax plus case-insensitive variant/singleton uniqueness.
/// @dev This does not prove dated IANA subtag registration or extension-specific semantics.
/// Original tag bytes are never rewritten; lowercase bytes exist only for parsing/comparison.
library StreamConservationLanguage {
    error InvalidConservationLanguage();

    /// @notice Validate ordered tags in one linked call and emit their exact ASCII JSON array.
    /// @dev Accepted tag bytes contain only ALNUM/hyphen, so none need JSON escaping.
    function arrayJSON(string[] memory values) public pure returns (string memory) {
        if (values.length == 0) revert InvalidConservationLanguage();
        uint256 size = 2;
        for (uint256 i; i < values.length; ++i) {
            size += bytes(values[i]).length + 2 + (i == 0 ? 0 : 1);
            if (size > 8192) revert InvalidConservationLanguage();
            requireWellFormed(values[i]);
        }
        bytes memory out = new bytes(size);
        out[0] = "[";
        uint256 at = 1;
        for (uint256 i; i < values.length; ++i) {
            if (i != 0) out[at++] = ",";
            out[at++] = '"';
            bytes memory value = bytes(values[i]);
            for (uint256 j; j < value.length; ++j) {
                out[at++] = value[j];
            }
            out[at++] = '"';
        }
        out[at] = "]";
        return string(out);
    }

    function requireWellFormed(string memory value) public pure {
        (bytes memory b, uint256[] memory parts) = _parts(value);
        // A single2..8ASCII-alpha primary already satisfies the complete original grammar.
        // Grandfathered tags are all multipart; preserve their existing path and exact bytes.
        if (parts.length == 1 && _size(parts[0]) >= 2 && _alpha(b, parts[0])) return;
        if (_grandfathered(keccak256(b))) return;
        uint256 n = parts.length;
        if (_size(parts[0]) == 1 && b[0] == "x") {
            if (n == 1) revert InvalidConservationLanguage();
            return;
        }
        uint256 languageLength = _size(parts[0]);
        if (languageLength < 2 || !_alpha(b, parts[0])) revert InvalidConservationLanguage();
        uint256 i = 1;
        if (languageLength <= 3) {
            uint256 count;
            while (i < n && count < 3 && _size(parts[i]) == 3 && _alpha(b, parts[i])) {
                ++i;
                ++count;
            }
        }
        if (i < n && _size(parts[i]) == 4 && _alpha(b, parts[i])) ++i;
        if (
            i < n
                && ((_size(parts[i]) == 2 && _alpha(b, parts[i]))
                    || (_size(parts[i]) == 3 && _digits(b, parts[i])))
        ) ++i;

        bytes32[] memory variants = new bytes32[](n);
        uint256 variantCount;
        while (i < n && _variant(b, parts[i])) {
            variants[variantCount++] = _hashPart(b, parts[i]);
            ++i;
        }
        _unique(variants, variantCount);

        uint256 singletons;
        while (i < n && _size(parts[i]) == 1 && b[parts[i] >> 8] != "x") {
            uint256 bit = uint256(1) << uint8(b[parts[i] >> 8]);
            if (singletons & bit != 0) revert InvalidConservationLanguage();
            singletons |= bit;
            ++i;
            uint256 start = i;
            while (i < n && _size(parts[i]) >= 2) ++i;
            if (i == start) revert InvalidConservationLanguage();
        }
        if (i < n && _size(parts[i]) == 1 && b[parts[i] >> 8] == "x") {
            ++i;
            if (i == n) revert InvalidConservationLanguage();
            // Every remaining part already satisfies private-use's1..8ALNUM production.
            i = n;
        }
        if (i != n) revert InvalidConservationLanguage();
    }

    function _parts(string memory value)
        private
        pure
        returns (bytes memory b, uint256[] memory parts)
    {
        bytes memory original = bytes(value);
        uint256 length = original.length;
        if (length == 0 || length > 8192 || original[0] == "-" || original[length - 1] == "-") {
            revert InvalidConservationLanguage();
        }
        b = new bytes(length);
        uint256 count = 1;
        for (uint256 i; i < length; ++i) {
            uint8 c = uint8(original[i]);
            if (c >= 65 && c <= 90) c += 32;
            if (c == 45) {
                if (i != 0 && original[i - 1] == "-") revert InvalidConservationLanguage();
                ++count;
            } else if (!((c >= 97 && c <= 122) || (c >= 48 && c <= 57))) {
                revert InvalidConservationLanguage();
            }
            b[i] = bytes1(c);
        }
        parts = new uint256[](count);
        uint256 start;
        uint256 index;
        for (uint256 i; i <= length; ++i) {
            if (i == length || b[i] == "-") {
                uint256 size = i - start;
                if (size == 0 || size > 8) revert InvalidConservationLanguage();
                parts[index++] = start << 8 | size;
                start = i + 1;
            }
        }
    }

    function _size(uint256 part) private pure returns (uint256) {
        return part & 255;
    }

    function _alpha(bytes memory b, uint256 part) private pure returns (bool) {
        uint256 start = part >> 8;
        uint256 end = start + _size(part);
        for (uint256 i = start; i < end; ++i) {
            if (b[i] < "a" || b[i] > "z") return false;
        }
        return true;
    }

    function _digits(bytes memory b, uint256 part) private pure returns (bool) {
        uint256 start = part >> 8;
        uint256 end = start + _size(part);
        for (uint256 i = start; i < end; ++i) {
            if (b[i] < "0" || b[i] > "9") return false;
        }
        return true;
    }

    function _variant(bytes memory b, uint256 part) private pure returns (bool) {
        uint256 size = _size(part);
        return size >= 5 || (size == 4 && b[part >> 8] >= "0" && b[part >> 8] <= "9");
    }

    function _hashPart(bytes memory b, uint256 part) private pure returns (bytes32) {
        bytes memory out = new bytes(_size(part));
        for (uint256 i; i < out.length; ++i) {
            out[i] = b[(part >> 8) + i];
        }
        return keccak256(out);
    }

    function _unique(bytes32[] memory hashes, uint256 n) private pure {
        for (uint256 i = n / 2; i != 0;) {
            --i;
            _sift(hashes, i, n);
        }
        for (uint256 end = n; end > 1;) {
            --end;
            (hashes[0], hashes[end]) = (hashes[end], hashes[0]);
            _sift(hashes, 0, end);
        }
        for (uint256 i = 1; i < n; ++i) {
            if (hashes[i - 1] == hashes[i]) revert InvalidConservationLanguage();
        }
    }

    function _sift(bytes32[] memory hashes, uint256 root, uint256 n) private pure {
        while (root < n / 2) {
            uint256 child = root * 2 + 1;
            if (child + 1 < n && hashes[child] < hashes[child + 1]) ++child;
            if (hashes[root] >= hashes[child]) return;
            (hashes[root], hashes[child]) = (hashes[child], hashes[root]);
            root = child;
        }
    }

    /// @dev The complete permanent26-tag regular/irregular set in RFC5646 section2.1.
    function _grandfathered(bytes32 h) private pure returns (bool) {
        return h == keccak256("en-gb-oed") || h == keccak256("i-ami") || h == keccak256("i-bnn")
            || h == keccak256("i-default") || h == keccak256("i-enochian")
            || h == keccak256("i-hak") || h == keccak256("i-klingon") || h == keccak256("i-lux")
            || h == keccak256("i-mingo") || h == keccak256("i-navajo") || h == keccak256("i-pwn")
            || h == keccak256("i-tao") || h == keccak256("i-tay") || h == keccak256("i-tsu")
            || h == keccak256("sgn-be-fr") || h == keccak256("sgn-be-nl")
            || h == keccak256("sgn-ch-de") || h == keccak256("art-lojban")
            || h == keccak256("cel-gaulish") || h == keccak256("no-bok") || h == keccak256("no-nyn")
            || h == keccak256("zh-guoyu") || h == keccak256("zh-hakka") || h == keccak256("zh-min")
            || h == keccak256("zh-min-nan") || h == keccak256("zh-xiang");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./StreamRecordJson.sol";
import "./StreamConservationDefinitions.sol";
import "../../interfaces/stream/metadata/StreamConservationRecordTypes.sol";

/// @notice Closed conservation fields; references are commitments, never verified external facts.
library StreamConservationRecordFields {
    error InvalidConservationWitness();

    function referenceJSON(StreamConservationRecordTypes.Reference memory r)
        public
        pure
        returns (string memory)
    {
        if (r.canonicalizationId == 0 || r.algorithm == 0 || r.algorithm > 6) {
            revert InvalidConservationWitness();
        }
        if (r.algorithm == 4 || r.algorithm == 5) {
            if (r.digest.length == 0 || r.digest.length > 128) revert InvalidConservationWitness();
        } else if (r.digest.length != 32) {
            revert InvalidConservationWitness();
        }
        StreamMetadataRenderer.requireValidUtf8ContentUri(
            "CONSERVATION_REFERENCE", r.uri, 2048, false
        );
        return string.concat(
            '{"hash":{"algorithm":',
            string(abi.encodePacked(bytes1(uint8(48 + r.algorithm)))),
            ',"canonicalizationId":',
            StreamRecordJson.hexValue(r.canonicalizationId),
            ',"digest":',
            _hexBytes(r.digest),
            '},"uri":',
            StreamRecordJson.quote(r.uri, 2048, false),
            "}"
        );
    }

    function requireEmptyReference(StreamConservationRecordTypes.Reference memory r) public pure {
        if (
            r.algorithm != 0 || r.canonicalizationId != 0 || r.digest.length != 0
                || bytes(r.uri).length != 0
        ) {
            revert InvalidConservationWitness();
        }
    }

    function requireHeader(bytes32 subjectId, bytes32 profileHash, bytes32 expectedProfile)
        public
        pure
    {
        if (subjectId == 0 || profileHash != expectedProfile) {
            revert InvalidConservationWitness();
        }
    }

    function artistJSON(StreamConservationRecordTypes.ArtistClaim memory a)
        public
        pure
        returns (string memory)
    {
        if (a.artistId == 0 || a.bindingGeneration == 0 || a.bindingHash == 0) {
            revert InvalidConservationWitness();
        }
        return string.concat(
            '{"artistId":',
            StreamRecordJson.hexValue(a.artistId),
            ',"bindingGeneration":',
            StreamRecordJson.unsigned(a.bindingGeneration),
            ',"bindingHash":',
            StreamRecordJson.hexValue(a.bindingHash),
            ',"statementOrigin":',
            a.origin == StreamConservationRecordTypes.StatementOrigin.ARTIST_INTENT
                ? '"artist_intent"'
                : '"estate_statement"',
            "}"
        );
    }

    function interviewJSON(StreamConservationRecordTypes.InterviewEntry memory e)
        public
        pure
        returns (string memory)
    {
        StreamConservationRecordTypes.InterviewRecord memory r = e.record;
        if (e.status == StreamConservationRecordTypes.InterviewStatus.PRESENT) {
            requireEmptyReference(e.waiverStatement);
            if (
                r.chainId == 0 || r.core == address(0) || r.host == address(0) || r.recordHash == 0
                    || r.schemaId != StreamConservationDefinitions.INTERVIEW_SCHEMA_ID
                    || r.profileHash != StreamConservationDefinitions.INTERVIEW_PROFILE_HASH
            ) revert InvalidConservationWitness();
            string memory locator = string.concat(
                '{"chainId":',
                StreamRecordJson.unsigned(r.chainId),
                ',"core":',
                StreamRecordJson.account(r.core),
                ',"host":',
                StreamRecordJson.account(r.host),
                ',"profileHash":',
                StreamRecordJson.hexValue(r.profileHash),
                ',"recordHash":',
                StreamRecordJson.hexValue(r.recordHash),
                ',"schemaId":',
                StreamRecordJson.hexValue(r.schemaId),
                "}"
            );
            return string.concat(
                '{"kind":"present","payload":', referenceJSON(r.payload), ',"record":', locator, "}"
            );
        }
        if (
            r.chainId != 0 || r.core != address(0) || r.host != address(0) || r.recordHash != 0
                || r.schemaId != 0 || r.profileHash != 0
        ) revert InvalidConservationWitness();
        requireEmptyReference(r.payload);
        return string.concat(
            '{"kind":"interview_waived","statement":', referenceJSON(e.waiverStatement), "}"
        );
    }

    /// @notice Preserve every row and its order with one bounded output allocation.
    function arrayJSON(bytes[] memory rows) public pure returns (string memory) {
        uint256 size = 2;
        for (uint256 i; i < rows.length; ++i) {
            size += rows[i].length + (i == 0 ? 0 : 1);
            if (size > 8192) revert InvalidConservationWitness();
        }
        bytes memory out = new bytes(size);
        out[0] = "[";
        uint256 offset = 1;
        for (uint256 i; i < rows.length; ++i) {
            if (i != 0) out[offset++] = ",";
            _copyRow(rows[i], out, offset);
            offset += rows[i].length;
        }
        out[offset] = "]";
        return string(out);
    }

    function requirePayloadSize(bytes memory value) public pure returns (bytes memory) {
        if (value.length == 0 || value.length > 8192) revert InvalidConservationWitness();
        return value;
    }

    function _hexBytes(bytes memory input) private pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory out = new bytes(4 + input.length * 2);
        out[0] = '"';
        out[1] = "0";
        out[2] = "x";
        out[out.length - 1] = '"';
        for (uint256 i; i < input.length; ++i) {
            out[3 + i * 2] = alphabet[uint8(input[i]) >> 4];
            out[4 + i * 2] = alphabet[uint8(input[i]) & 15];
        }
        return string(out);
    }

    function _copyRow(bytes memory row, bytes memory out, uint256 offset) private pure {
        assembly ("memory-safe") {
            let size := mload(row)
            let source := add(row, 32)
            let target := add(add(out, 32), offset)
            let cursor := 0
            for { } iszero(gt(add(cursor, 32), size)) { cursor := add(cursor, 32) } {
                mstore(add(target, cursor), mload(add(source, cursor)))
            }
            if lt(cursor, size) {
                let tail := mload(add(source, cursor))
                let index := 0
                for { } lt(cursor, size) {
                    cursor := add(cursor, 1)
                    index := add(index, 1)
                } { mstore8(add(target, cursor), byte(index, tail)) }
            }
        }
    }
}

