        0x1de4ffe22d9442b4aa3447fef5057f6677f167ce901c76555d17c25aece44755;
    uint256 internal constant PROFILE_BYTES = 2283;
    bytes32 internal constant CANON_ID = keccak256("RFC8785_JCS");
    bytes32 internal constant CANON_HASH =
        0xbc33af15c6b6374052871a5fdfa255f900f56fa594f650b2d0814c681fdb35a9;
    uint256 internal constant CANON_BYTES = 362;
}

