        UNSPECIFIED,
        COPYRIGHT,
        LICENSE,
        STATUTE,
        PUBLIC_DOMAIN,
        CONTRACT
    }
    enum Status {
        UNSPECIFIED,
        GRANTED,
        GRANTED_WITH_CONDITIONS,
        DENIED
    }
    enum LicensorKind {
        ARTIST,
        ESTATE,
        INSTITUTION,
        ACCOUNT
    }
    enum ConditionKind {
        NONE,
        TEXT,
        DOCUMENT
    }

