        LicensorKind kind;
        bytes32 artistId;
        string name;
        address account;
        bytes32 instrumentDigest;
    }

    struct Conditions {
        ConditionKind kind;
        string text;
        Document document;
    }

    struct Grant {
        Status status;
        Conditions conditions;
        string extension;
    }

    /// @dev Named fields prevent missing, duplicated or reordered use-class witnesses.
    struct Grants {
        Grant aiTraining;
        Grant derivative;
        Grant exhibition;
        Grant print;
        Grant publication;
        Grant reproduction;
    }

